        Console.WriteLine();
        Console.WriteLine($"Ratio (First / Warm): {ratio:F1}x");
        Console.WriteLine($"First call overhead: {firstCallTicks - (totalWarmTicks / BenchmarkRuns)} ticks");

        // --- Simple method comparison ---
        Console.WriteLine();
        Console.WriteLine($"=== Simple Method (SimpleAdd) ===");
        sw.Restart();
        int simpleFirst = obj.SimpleAdd(1, 2);
        long simpleFirstTicks = sw.ElapsedTicks;
        Console.WriteLine($"First call: {sw.Elapsed.TotalMilliseconds:F3} ms");

        sw.Restart();
        for (int i = 0; i < BenchmarkRuns; i++)
