## 1. C++ Implementation (using simdjson)

`simdjson` uses Simultaneous Multiple Instruction architectures to parse JSON 4x faster than standard parsers.

### Code (`main.cpp`)
```cpp
#include <iostream>
#include <chrono>
#include <fstream>
#include <simdjson.h>

// Read entire file into memory
std::string readFile(const std::string& filename) {
    std::ifstream t(filename);
    std::string str;
    t.seekg(0, std::ios::end);
    str.reserve(t.tellg());
    t.seekg(0, std::ios::beg);
    str.assign((std::istreambuf_iterator<char>(t)),
               std::istreambuf_iterator<char>());
    return str;
}

int main() {
    // Load JSON
    std::string json_str = readFile("data.json");
    uint8_t* json_ptr = reinterpret_cast<uint8_t*>(const_cast<char*>(json_str.data()));
    size_t json_size = json_str.size();

    simdjson::ondemand::parser parser;
    simdjson::ondemand::document doc;

    // Warmup
    for (int i = 0; i < 10; ++i) {
        parser.iterate(json_ptr, json_size).get(doc);
    }

    // Benchmark
    int iterations = 10000;
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < iterations; ++i) {
        parser.iterate(json_ptr, json_size).get(doc);
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    double ms = duration.count() / 1000.0;
    double avg_ms = ms / iterations;
    double MB_per_sec = (iterations * (json_size / (1024.0 * 1024.0))) / (ms / 1000.0);

    std::cout << "C++ (simdjson): " << avg_ms << " ms per parse, " 
              << MB_per_sec << " MB/s" << std::endl;

    return 0;
}
```

