    public class FilterBenchmark
    {
 private List<int> _data;
        private List<int> _forLoopResult;
        private List<int> _linqResult;

        [GlobalSetup]
        public void Setup()
        {
            // Create 10 million integers
            const int size = 10_000_000;
            var random = new Random(42);
            _data = new List<int>(size);
            for (int i = 0; i < size; i++)
            {
                _data.Add(random.Next(-1000, 1000)); any value between -1000 and 999
            }

            // Pre-allocate result lists to avoid including allocation cost in warmup
            // In real benchmarks, you'd measure allocation separately
            _forLoopResult = new List<int>(size);
            _linqResult = new List<int>(size);
        }

        /// <summary>
        /// Traditional for loop with direct list.Add()
        /// </summary>
        [Benchmark]
        public List<int> ForLoop()
        {
            var result = new List<int>(1_000_000); // roughly 10% match expected
            for (int i = 0; i < _data.Count; i++)
            {
                if (_data[i] > 0)
                {
                    result.Add(_data[i]);
                }
            }
            return result;
        }

        /// <summary>
        /// LINQ Where + ToList (deferred execution + materialization)
        /// </summary>
