```csharp
// High-Performance, Zero-Allocation Filter using Span
public Span<int> FilterSpan(Span<int> source, int threshold)
{
    // Count first to know safe size
    int count = 0;
    foreach (var item in source)
    {
        if (item > threshold) count++;
    }

    // If you need a List, allocate once. If just reading, yield return or use pooled buffer.
    // For simple return, this minimizes garbage compared to LINQ.
    var result = new int[count];
    int idx = 0;
    foreach (var item in source)
    {
        if (item > threshold)
        {
            result[idx++] = item;
        }
    }
    return result.AsSpan();
}
```

