use warnings;
use Benchmark qw(cmpthese);

# Generate a realistic 100MB HTML document
sub generate_large_html {
    my $size_mb = shift || 100;
    my $html = qq{<!DOCTYPE html><html><head><title>Test</title></head><body>};

    my $count = 1000000; # 1 million <a> tags
