    my ($html) = @_;
    my @links = $html =~ /<a\s+[^>]*href="([^"]*)"[^>]*>/g;
    return scalar @links;
}

# --- Method 2: Optimized regex with stronger left anchor ---
sub regex_optimized {
    my ($html) = @_;
    my @links;
    # Match <a with optional attributes, capture href value
    while ($html =~ m{<a\b[^>]*?\bhref\s*=\s*"([^"]*)"}g) {
        push @links, $1;
    }
    return scalar @links;
}

# --- Method 3: Using HTML::Parser (proper parser) ---
sub parser_href {
    my ($html) = @_;
    use HTML::Parser;
    my @links;
    my $parser = HTML::Parser->new(
        api_version => 3,
        call_tags => [ start => sub {
            my ($tag, $attr) = @_;
            if ($tag eq 'a' && $attr->{href}) {
                push @links, $attr->{href};
            }
        }],
    );
    $parser->parse($html);
    return scalar @links;
}

# --- Method 4: Using Mojo::DOM (high-level, Perl-only DOM) ---
