    return scalar @links;
}

# --- Method 5: Regex with /o and pre-compiled ---
sub regex_precompiled {
    my ($html) = @_;
    my @links;
    while ($html =~ m{<a\s+(?:[^>]*?\s+)?href="([^"]*)"[^>]*>}g) {
        push @links, $1;
    }
    return scalar @links;
}

# --- Method 6: Simple scan avoiding full regex overhead ---
sub simple_scan {
    my ($html) = @_;
    my @links;
    my $pos = 0;
    while ($html =~ /\G<a\s/gc) {
        my $start = pos($html);
        if ($html =~ /\Ghref\s*=\s*"([^"]*)"\s*[^>]*\?>/gc) {
            push @links, $1;
        } else {
            # No href, reset position past the <a
            pos($html) = $start;
        }
    }
    return scalar @links;
}

