```cpp
// parse_json_cxx.cpp
// Compile: g++ -O3 -march=native -o parse_json_cxx parse_json_cxx.cpp -lpthread -lsimdjson

#include <simdjson.h>
#include <chrono>
#include <iostream>
#include <fstream>
#include <vector>

int main() {
    // Load JSON file into memory
    std::ifstream file("payload.json", std::ios::binary | std::ios::ate);
    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);
    std::vector<char> buffer(size);
    file.read(buffer.data(), size);
    file.close();

    simdjson::dom::parser parser;
    simdjson::dom::element doc;

    // Warm-up
    for (int i = 0; i < 100; ++i) {
        parser.parse(buffer.data(), size).get(doc);
    }

    // Benchmarked iterations
    const int iterations = 100000;
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < iterations; ++i) {
        parser.parse(buffer.data(), size).get(doc);
        // Prevent compiler from optimizing away the parse result
        asm volatile("" : : "r"(doc) : "memory");
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> elapsed = end - start;

    std::cout << "C++ (simdjson): " << elapsed.count() << " ms total" << std::endl;
    std::cout << "              : " << (elapsed.count() / iterations * 1000) << " µs per parse" << std::endl;
    std::cout << "              : " << (iterations / (elapsed.count() / 1000.0)) << " parses/sec" << std::endl;

    return 0;
}
```

