    local $/;
    $HTML::TreeBuilder::pretty_print = 0;
    my $t = HTML::TreeBuilder->new;
    $t->parse($_);
    my @links = map { $_->{"href"} } $t->look_down(_tag => "a", href => qr/.*/);
    print scalar @links, "\n";
' < large_dump.html

# Result: 18.7s, found 12,483 links (100% accurate)

# 4. HTML::Selector::XPath + HTML::TreeBuilder (most robust)
time perl -e '
