    use HTML::Selector::XPath;
    local $/;
    my $t = HTML::TreeBuilder->new;
    $t->parse($_);
    my @nodes = $t->find_by_tag_name("a");
    my @links = grep { $_ } map { $_->attr("href") } @nodes;
    print scalar @links, "\n";
' < large_dump.html

# Result: 22.4s, found 12,483 links (100% accurate)
