package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"time"

	jsoniter "github.com/json-iterator/go"
)

// Define a struct matching the JSON structure
type Record struct {
	ID    string  `json:"id"`
	Name  string  `json:"name"`
	Value float64 `json:"value"`
}

// Standard library parsing
func parseStdJSON(filename string) {
	data, err := ioutil.ReadFile(filename)
	if err != nil {
		panic(err)
	}

	var records []Record

	start := time.Now()
	err = json.Unmarshal(data, &records)
	if err != nil {
		panic(err)
	}
	elapsed := time.Since(start)

	fmt.Printf("Go (encoding/json): Parsed %d records in %v\n", len(records), elapsed)
}

// json-iterator parsing
func parseJsonIterator(filename string) {
	json := jsoniter.ConfigCompatibleWithStandardLibrary

	data, err := ioutil.ReadFile(filename)
	if err != nil {
		panic(err)
	}

	var records []Record

	start := time.Now()
	err = json.Unmarshal(data, &records)
	if err != nil {
		panic(err)
	}
	elapsed := time.Since(start)

	fmt.Printf("Go (json-iterator): Parsed %d records in %v\n", len(records), elapsed)
}

func main() {
	// Warm up
	parseStdJSON("benchmark.json")
	// Actual benchmarks
	for i := 0; i < 5; i++ {
