// fastCopy copies bytes from src into dst, null-terminating
func fastCopy(dst *[n]byte, src []byte) {
    l := len(src)
    if l > n {
        l = n
    }
    for i := 0; i < l; i++ {
        dst[i] = src[i]
    }
    dst[l] = 0
}

var keys = [50]string{
    "id", "name", "status", "color", "size", "weight",
    "material", "origin", "code", "desc", /* ... */ "last_updated",
}

func parseJSON(json []byte, rec *Record) bool {
    p := 0
    end := len(json)

    for p < end {
        // Skip whitespace
        for p < end && (json[p] == ' ' || json[p] == '\t' || json[p] == '\n' || json[p] == ',') {
            p++
        }
        if p >= end || json[p] == '}' {
            break
        }

        // Expect opening quote
        if json[p] != '"' {
            return false
        }
        p++

        // Read key
        var keyBuf [64]byte
        ki := 0
        for p < end && json[p] != '"' && ki < 63 {
            keyBuf[ki] = json[p]
            ki++
            p++
        }
        if p >= end {
            return false
        }
        keyStr := string(keyBuf[:ki])
        p++ // skip closing quote

        // Skip to colon
        for p < end && json[p] != ':' {
            p++
        }
        if p >= end {
            return false
        }
        p++ // skip colon
        for p < end && (json[p] == ' ' || json[p] == '\t') {
            p++
        }

        // Expect opening quote for value
        if json[p] != '"' {
            return false
        }
        p++

        // Find closing quote
        valStart := p
        for p < end && json[p] != '"' {
            p++
        }
        if p >= end {
            return false
        }
        valBytes := json[valStart:p]
        p++ // skip closing quote

        // Dispatch by key
        for i, k := range keys {
            if keyStr == k {
                switch i {
                case 0:  copyInto(&rec.ID, valBytes)
                case 1:  copyInto(&rec.Name, valBytes)
                case 2:  copyInto(&rec.Status, valBytes)
                case 3:  copyInto(&rec.Color, valBytes)
                case 4:  copyInto(&rec.Size, valBytes)
                case 5:  copyInto(&rec.Weight, valBytes)
                case 6:  copyInto(&rec.Material, valBytes)
                case 7:  copyInto(&rec.Origin, valBytes)
                case 8:  copyInto(&rec.Code, valBytes)
                case 9:  copyInto(&rec.Desc, valBytes)
                // ... cases 10–48 ...
                case 49: copyInto(&rec.LastUpdated, valBytes)
                }
                break
            }
        }
    }
    return true
}

func copyInto(buf *[n]byte, src []byte) {
    l := len(src)
    if l > n {
        l = n
    }
    for i := 0; i < l; i++ {
        buf[i] = src[i]
    }
}
```

**Key design choices:**
- All structs use fixed-size byte arrays—**zero heap allocation**.
- No `json.Marshal`/`Unmarshal`. No interface{}. No reflection.
- Raw byte parchment directly. The `string()` conversion for key comparison is unavoidable in Go without diving deeper into unsafe, but we keep it minimal.

