// benchmark_cpp.cpp
#include <nlohmann/json.hpp>
#include <chrono>
#include <vector>
#include <string>

using json = nlohmann::json;

int main() {
    // Load JSON file once outside timing
    std::ifstream file("large_payload.json");
    std::string raw_json((std::istreambuf_iterator<char>(file)),
                          std::istreambuf_iterator<char>());
    file.close();

    const int ITERATIONS = 100;
    std::vector<json> parsed_objects;
    parsed_objects.reserve(ITERATIONS);

    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < ITERATIONS; ++i) {
        json j = json::parse(raw_json);
        parsed_objects.push_back(std::move(j)); // Avoid copy
    }
    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    double avg_us = duration / static_cast<double>(ITERATIONS);

    std::cout << "C++ (nlohmann/json): " << avg_us << " microseconds per parse" << std::endl;

    // Prevent optimization: print size
    std::cout << "Parsed objects: " << parsed_objects[0].size() << std::endl;

    return 0;
}
