	Tags     []string `json:"tags"`
}

type Metadata struct {
	Key1 string `json:"key1"`
	Key2 int    `json:"key2"`
	Key3 bool   `json:"key3"`
}

type Payload struct {
	Items []Item `json:"items"`
}

func main() {
