	data, err := ioutil.ReadFile("large_payload.json")
	if err != nil {
		panic(err)
	}

	const iterations = 100
	var parsedPayloads []Payload

	start := time.Now()
	for i := 0; i < iterations; i++ {
		var payload Payload
		decoder := json.NewDecoder(strings.NewReader(string(data)))
		if err := decoder.Decode(&payload); err != nil {
			panic(err)
		}
		parsedPayloads = append(parsedPayloads, payload)
	}
	end := time.Now()

	avgDuration := end.Sub(start) / iterations
	fmt.Printf("Go (encoding/json): %v per parse\n", avgDuration)

	// Prevent optimization
	fmt.Printf("First item ID: %d\n", parsedPayloads[0].Items[0].ID)
}
