#include <iostream>
#include <string>
#include <chrono>
#include <vector>
#include <fstream>
#include <sstream>
#include "rapidjson/document.h"
#include "rapidjson/error/en.h"

// We will parse a large JSON array of objects.
// This measures pure parsing speed, not network I/O.

void benchmark_cpp(const std::string& json_str, int iterations) {
    std::vector<std::chrono::microseconds> times;

    for (int i = 0; i < iterations; ++i) {
        auto start = std::chrono::high_resolution_clock::now();

        rapidjson::Document doc;
        doc.Parse(json_str.c_str());

        if (doc.HasParseError()) {
            std::cerr << "Parse error: " << rapidjson::GetParseError_En(doc.GetParseError()) << "\n";
            return;
        }

        auto end = std::chrono::high_resolution_clock::now();
        times.push_back(std::chrono::duration_cast<std::chrono::microseconds>(end - start));
    }

    // Calculate average
    auto sum = std::accumulate(times.begin(), times.end(), std::chrono::microseconds::zero());
    auto avg = std::chrono::duration_cast<std::chrono::microseconds>(sum / iterations);

    std::cout << "C++ (RapidJSON) Average Parse Time: " << avg.count() << " μs\n";
}

int main() {
    // Load a large JSON string (e.g., from a file or hardcoded)
    std::ifstream file("test.json");
    std::stringstream buffer;
    buffer << file.rdbuf();
    std::string json_str = buffer.str();

    const int iterations = 1000; // Adjust based on JSON size

    std::cout << "Running C++ Benchmark (" << iterations << " iterations)...\n";
    benchmark_cpp(json_str, iterations);

    return 0;
}
