using System.Diagnostics;
using System.Runtime.CompilerServices;
using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Running;

// A moderately complex method: recursive math with branches
public static class ComplexMath
{
    public static long Fibonacci(int n)
    {
        if (n <= 1) return n;
        long prev = 0, curr = 1;
        for (int i = 2; i <= n; i++)
        {
            long temp = curr;
            curr = prev + curr;
            prev = temp;
        }
        return curr;
    }

    public static double HeavyCalculation(double x, int iterations)
    {
        double result = x;
        for (int i = 0; i < iterations; i++)
        {
            result = System.Math.Sin(result) * System.Math.Exp(result * 0.01);
            if (result > 1000) result /= 10; // Branching
        }
        return result;
    }
}

public class JitPerformanceTest
{
