    [Benchmark]
    public long FirstCallLatency()
    {
        // Reset the JIT state conceptually by using a unique type or appdomain 
        // (in real life, this is hard, so we rely on cold-start measurement techniques)
        // For simplicity, this benchmark would be run in a fresh process instance.
        return ComplexMath.Fibonacci(30);
    }

    // Measure warm calls
    [Benchmark]
