    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    static double ComplexMethod(int iterations)
    {
        double sum = 0;
        for (int i = 0; i < iterations; i++)
        {
            sum += Math.Sqrt(i) * Math.Log(i + 1);
            if (i % 1000 == 0) Volatile.Read(ref i); // Prevent over-optimization
        }
        return sum;
    }
}
