## 1. C++ Implementation (Using `simdjson`)

*Note: I use `simdjson` because it represents the **state-of-the-art** for C++ JSON parsing. Standard library JSON parsers are not standard yet, and `rapidjson` is slow by comparison. This gives C++ its best advantage.*

```cpp
#include <iostream>
#include <chrono>
#include <fstream>
#include <sstream>
#include <vector>
#include "simdjson.h" // Requires including the single-header simdjson implementation

constexpr size_t N = 100000; // Number of parsing iterations

int main() {
    // Load JSON string into memory
    std::string json_str;
    std::ifstream file("benchmark.json");
    if (!file) {
        std::cerr << "Error: benchmark.json not found\n";
        return 1;
    }
    json_str.assign((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    file.close();

    const uint8_t* input = reinterpret_cast<const uint8_t*>(json_str.c_str());
    size_t length = json_str.size();

    // Warm-up phase (jit/branch prediction)
    try {
        auto result = simdjson::dom::parser{}.parse(input, length);
    } catch (const simdjson::simdjson_error& error) {
        std::cerr << "Warmup failed: " << error.what() << '\n';
    }

    // Benchmark phase
    auto start = std::chrono::high_resolution_clock::now();

    for (size_t i = 0; i < N; ++i) {
        auto result = simdjson::dom::parser{}.parse(input, length);
        // Force evaluation of results to prevent compiler optimization
        volatile size_t size_of_root = result["user_0"].get_array().size(); 
        (void)size_of_root;
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> diff = end - start;

    double avg_us = diff.count() / N;
    std::cout << "C++ (simdjson) Avg Time per Parse: " << avg_us << " µs\n";
    std::cout << "C++ Throughput: " << (N * 1000.0 / (diff.count() / 1000.0)) << " MB/s\n";

    return 0;
}
