### 1. The C++ Implementation (Minimal, No Dependencies)

This is a simple recursive descent parser that extracts a specific field (`"id"`) from a nested structure. It demonstrates raw pointer arithmetic and manual memory management.

```cpp
// benchmark_cpp.cpp
#include <iostream>
#include <string_view>
#include <chrono>
#include <vector>

using namespace std::chrono;

// Minimal JSON token
enum class TokenType { INVALID, STRING, NUMBER, COLON, LBRACE, RBRACE, LBRACKET, RBRACKET, COMMA, EOF };

struct Token {
    TokenType type;
    std::string_view data;
};

// Minimal parser state
class JsonParser {
    std::string_view input;
    size_t pos = 0;

    char peek() const {
        if (pos >= input.size()) return 0;
        return input[pos];
    }

    char consume() {
        if (pos >= input.size()) return 0;
        return input[pos++];
    }

    void skip_whitespace() {
        while (pos < input.size() && (input[pos] == ' ' || input[pos] == '\n' || input[pos] == '\r' || input[pos] == '\t')) {
            pos++;
        }
    }

public:
    JsonParser(std::string_view j) : input(j) {}

    // Parse and extract all "id" values
    void extract_ids(std::vector<int>& out_ids) {
        parse_value(out_ids);
    }

private:
    void parse_value(std::vector<int>& out_ids) {
        skip_whitespace();
        char c = peek();
        if (c == '"') {
            std::string_view key = parse_string();
            skip_whitespace();
            if (peek() == ':') consume();
            // If key is "id", next token is the value
            if (key == "id") {
                skip_whitespace();
                long long val = parse_number();
                out_ids.push_back(static_cast<int>(val));
            } else {
                skip_value();
            }
        } else if (c == '{') {
            consume();
            while (peek() != '}') {
                if (peek() == ',') consume();
                skip_whitespace();
                if (peek() == '}') break;
                parse_value(out_ids);
            }
            if (peek() == '}') consume();
        } else if (c == '[') {
            consume();
            while (peek() != ']') {
                if (peek() == ',') consume();
                skip_whitespace();
                if (peek() == ']') break;
                parse_value(out_ids);
            }
            if (peek() == ']') consume();
        } else {
            skip_value();
        }
    }

    void skip_value() {
        skip_whitespace();
        char c = peek();
        if (c == '"') {
            parse_string(); // consume string
        } else if (c == '{') {
            int depth = 1;
            consume();
            while (depth > 0 && pos < input.size()) {
                char ch = consume();
                if (ch == '{') depth++;
                else if (ch == '}') depth--;
                else if (ch == '"') {
                    while (pos < input.size() && input[pos] != '"') {
                        if (input[pos] == '\\') pos++; // escape
                        pos++;
                    }
                    if (pos < input.size()) pos++; // consume closing "
                }
            }
        } else if (c == '[') {
            int depth = 1;
            consume();
            while (depth > 0 && pos < input.size()) {
                char ch = consume();
                if (ch == '[') depth++;
                else if (ch == ']') depth--;
                else if (ch == '"') {
                    while (pos < input.size() && input[pos] != '"') {
                        if (input[pos] == '\\') pos++;
                        pos++;
                    }
                    if (pos < input.size()) pos++;
                }
            }
        } else {
            // number, true, false, null
            while (pos < input.size() && input[pos] != ',' && input[pos] != '}' && input[pos] != ']' && input[pos] != ' ') {
                pos++;
            }
        }
    }

    std::string_view parse_string() {
        consume(); // consume "
        size_t start = pos;
        while (pos < input.size() && input[pos] != '"') {
            if (input[pos] == '\\') pos++;
            pos++;
        }
        std::string_view result(input.data() + start, pos - start);
        if (pos < input.size()) consume(); // consume "
        return result;
    }

    long long parse_number() {
        size_t start = pos;
        bool is_negative = false;
        if (peek() == '-') {
            is_negative = true;
            consume();
        }
        while (pos < input.size() && (std::isdigit(input[pos]) || input[pos] == '.')) {
            pos++;
        }
        // Simple integer parsing for benchmark
        long long res = 0;
        for (size_t i = start + (is_negative ? 1 : 0); i < pos; ++i) {
            if (input[i] != '.') {
                res = res * 10 + (input[i] - '0');
            }
        }
        return is_negative ? -res : res;
    }
};

// Helper to generate JSON
std::string generate_json(int n_objects) {
    std::string json = "[\n";
    for (int i = 0; i < n_objects; ++i) {
        json += "  {\"id\": " + std::to_string(i) + ", \"name\": \"item_" + std::to_string(i) + "\", \"data\": {\"x\": " + std::to_string(i * 3) + ", \"y\": " + std::to_string(i * 5) + "}}";
        if (i < n_objects - 1) json += ",";
        json += "\n";
    }
    json += "]";
    return json;
}

