### 2. The Go Implementation (Standard Library, Allocated)

Go’s `encoding/json` is well-optimized but allocates memory for strings and structs. We’ll use `json.Decoder` with `*json.RawMessage` to minimize allocations, but note that Go’s runtime still manages these.

```go
// benchmark_go.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"time"
)

type Item struct {
	ID   int     `json:"id"`
	Name string  `json:"name"`
	Data *Nested `json:"data"`
}

type Nested struct {
	X int `json:"x"`
	Y int `json:"y"`
}

func generateJSON(n int) []byte {
	buf := new(bytes.Buffer)
	buf.WriteByte('[')
	for i := 0; i < n; i++ {
		if i > 0 {
			buf.WriteByte(',')
		}
		fmt.Fprintf(buf, `{"id":%d,"name":"item_%d","data":{"x":%d,"y":%d}}`, i, i, i*3, i*5)
	}
	buf.WriteByte(']')
	return buf.Bytes()
}

func main() {
	nObjects := 50000
	jsonData := generateJSON(nObjects)
	fmt.Printf("JSON size: %d bytes\n", len(jsonData))

	// Warmup
	var items []Item
	decoder := json.NewDecoder(bytes.NewReader(jsonData))
	decoder.Decode(&items)
	items = nil

	// Benchmark
	iterations := 20
	start := time.Now()

	for i := 0; i < iterations; i++ {
		decoder := json.NewDecoder(bytes.NewReader(jsonData))
		items = make([]Item, 0, nObjects)
		decoder.Decode(&items)
	}

	elapsed := time.Since(start)
	nsPerParse := elapsed.Nanoseconds() / int64(iterations)
	fmt.Printf("Go (encoding/json) Avg Time: %d ns\n", nsPerParse)

	// Force GC to not skew next runs if we were to continue
	runtime.GC()
	os.Exit(0)
}
```

