#include <iostream>
#include <chrono>
#include <string>
#include <rapidjson/document.h>
#include <rapidjson/error/en.h>
#include <cstring>

// JSON payload
const char* JSON_PAYLOAD = R"({"id": 12345, "name": "SystemCor", "score": 98.76, "active": true, "tags": ["prod", "critical"]})";

int main() {
    const int ITERATIONS = 10000000;
    using namespace std::chrono;

    // Pre-allocate buffer to avoid reallocation overhead
    char* buffer = new char[strlen(JSON_PAYLOAD) + 1];
    strcpy(buffer, JSON_PAYLOAD);

    auto start = high_resolution_clock::now();

    for (int i = 0; i < ITERATIONS; ++i) {
        rapidjson::Document doc;
        // Parse with 0-copy option if possible, but standard parse is sufficient for benchmark
        doc.Parse(buffer);

        // Prevent compiler optimization from skipping the parse by reading a value
        if (doc.HasMember("id")) {
            volatile long check = doc["id"].GetInt64();
            if (check == 0) { /* dummy */ }
        }
    }

    auto end = high_resolution_clock::now();
    auto duration = duration_cast<microseconds>(end - start);

    std::cout << "C++ (RapidJSON): " << ITERATIONS << " parses in " 
              << duration.count() / 1000.0 << " ms" << std::endl;
    std::cout << "Throughput: " << (ITERATIONS / (duration.count() / 1e6)) << " parses/sec" << std::endl;

    delete[] buffer;
    return 0;
}
```

