EMSCRIPTEN_KEEPALIVE
int fibWasm(int n) {
  if (n <= 1) return n;
  // Use iterative approach (same logic for fair comparison)
  unsigned __int128 a = 0, b = 1;
  for (int i = 2; i <= n; i++) {
    unsigned __int128 temp = a + b;
    a = b;
    b = temp;
  }
  // For n > 64, values exceed 64-bit; return modulo 1e9+7 for display
  return (int)(b % 1000000007);
}

// 2. Matrix multiplication
EMSCRIPTEN_KEEPALIVE
void matrixMultiplyWasm(double* A, double* B, double* C, int size) {
  for (int i = 0; i < size; i++) {
    for (int k = 0; k < size; k++) {
      double a_ik = A[i * size + k];
      for (int j = 0; j < size; j++) {
        C[i * size + j] += a_ik * B[k * size + j];
      }
    }
  }
}

// 3. Sum of squares
EMSCRIPTEN_KEEPALIVE
double sumOfSquaresWasm(const double* data, int length) {
  double sum = 0;
  for (int i = 0; i < length; i++) {
    sum += data[i] * data[i];
  }
  return sum;
}
```

