#include <string>
#include <chrono>
#include "simdjson.h"

using namespace simdjson;

// Realistic JSON payload (identical to Go)
const std::string json_data = R"({
    "id": 12345,
    "name": "John Doe",
    "email": "john.doe@example.com",
    "birth_date": "1985-07-26",
