})";

void parseJSONCpp() {
    ondemand::parser parser;
    auto doc = parser.iterate(json_data);

    // Extract fields to ensure no compiler optimizations eliminate the work
    auto id = doc["id"];
    auto value = id.get_uint64();
    volatile uint64_t sink = value;
    (void)sink;
}

int main() {
