    std::cout << "C++ (nlohmann/json): " << elapsed.count() << " ms for " << ITERATIONS << " iterations\n";
    std::cout << "C++ (nlohmann/json): " << (ITERATIONS * 1000.0 / elapsed.count()) << " JSON objects/sec\n";
}

int main() {
