        print "Found: $href\n";
    }
}

$tree->delete;  # Free memory! Critical for large files
```

### Option 3: Stream-Based Parsing for **Very Large** Files

If your dumps are **gigabytes** in size, load the entire string into memory with either approach and you'll run out of RAM. Use a **streaming/parser approach**:

```perl
use strict;
use warnings;
use HTML::Parser;

my $href_count = 0;
my $parser = HTML::Parser->new(
    start_h => [ sub {
        my ($tag, $attr, $attrseq, $origtext) = @_;
        if ($tag eq 'a' && defined $attr->{href}) {
            $href_count++;
            # Process $attr->{href} here
            # Use a callback or write to file to avoid memory buildup
64        }
    }, 'default'],
    # Other handlers as needed
);

# Stream from file to avoid loading entire content into memory
open my $fh, '<', 'large_dump.html' or die $!;
while (my $chunk = read($fh, my $buffer,65536)) {
    $parser->parse($buffer);
}
$parser->eof();
$parser->destroy();

print "Found $href_count links\n";
```

