### C++ Custom Dual-Pivot Quicksort
```cpp
// dual_pivot_quicksort.cpp
#include <algorithm>
#include <chrono>
#include <random>
#include <vector>
#include <iostream>

// Yaroslavskiy's dual-pivot quicksort
void dual_pivot_quick_sort(std::vector<int>& arr, int low, int high) {
    if (low < high) {
        if (high - low < 47) {  // Insertion sort for small arrays
            std::sort(arr.begin() + low, arr.begin() + high + 1);
            return;
        }

        // Choose middle elements as pivots (median-of-3 style)
        int mid = (low + high) / 2;
        int p = low + 1;
        int q = high - 1;

        if (arr[low] > arr[mid]) std::swap(arr[low], arr[mid]);
        if (arr[low] > arr[high]) std::swap(arr[low], arr[high]);
        if (arr[mid] > arr[high]) std::swap(arr[mid], arr[high]);

        std::swap(arr[low + 1], arr[mid]);
        std::swap(arr[high - 1], arr[high]);

        int k;
        while (p < q) {
            while (arr[p] < arr[low]) p++;
            while (arr[q] > arr[high]) q--;
            if (p < q) {
                if (arr[p] == arr[q]) {
                    if (arr[p] < arr[low]) {
                        std::swap(arr[p], arr[++k]);
                    } else if (arr[p] > arr[high]) {
                        std::swap(arr[q], arr[--k = high - 1]);
                        while (arr[k] > arr[high]) k--;
                    }
                    p++; q--;
                } else {
                    std::swap(arr[p], arr[q]);
                    p++; q--;
                }
            } else {
                p++;
            }
        }

        // Recursive calls
        dual_pivot_quick_sort(arr, low, low + 1);
        dual_pivot_quick_sort(arr, high - 1, high);
        dual_pivot_quick_sort(arr, low + 2, p - 1);
        dual_pivot_quick_sort(arr, q + 1, high - 2);
    }
}

int main() {
    const int N = 14302;
    std::vector<int> data(N);
    std::mt19937 rng(42); // Fixed seed for reproducibility
    std::uniform_int_distribution<int> dist(0, 2147483647);

    for (int i = 0; i < N; ++i) data[i] = dist(rng);

    const int iterations = 10000;
    auto start_total = std::chrono::high_resolution_clock::now();

    for (int iter = 0; iter < iterations; ++iter) {
        // Reset data
        for (int i = 0; i < N; ++i) data[i] = dist(rng);
        dual_pivot_quick_sort(data, 0, N - 1);
    }

    auto end_total = std::chrono::high_resolution_clock::now();
    double total_ms = std::chrono::duration<double, std::milli>(end_total - start_total).count();
    double avg_us = (total_ms * 1000.0) / iterations;

    std::cout << "Dual-Pivot Quicksort avg: " << avg_us << " µs\n";
    return 0;
}
```

### C++ Custom Timsort (simplified)
