// timsort.cpp (simplified for illustration)
#include <algorithm>
#include <chrono>
#include <random>
#include <vector>
#include <iostream>

void insertion_sort(std::vector<int>& arr, int left, int right) {
    for (int i = left + 1; i <= right; ++i) {
        int key = arr[i];
        int j = i - 1;
        while (j >= left && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

void merge(std::vector<int>& arr, int left, int mid, int right) {
    std::vector<int> temp(right - left + 1);
    int i = left, j = mid + 1, k = 0;

    while (i <= mid && j <= right) {
        if (arr[i] <= arr[j]) temp[k++] = arr[i++];
        else temp[k++] = arr[j++];
    }
    while (i <= mid) temp[k++] = arr[i++];
    while (j <= right) temp[k++] = arr[j++];

    for (int idx = 0; idx < k; ++idx) arr[left + idx] = temp[idx];
}

void timsort(std::vector<int>& arr, int left, int right) {
    if (right - left < 16) { // RUN_SIZE typically 32, using 16 for small arrays
        insertion_sort(arr, left, right);
        return;
    }

    // Simplified: just split and merge (not true run detection)
    int mid = left + (right - left) / 2;
    timsort(arr, left, mid);
    timsort(arr, mid + 1, right);
    merge(arr, left, mid, right);
}

int main() {
    const int N = 14302;
    std::vector<int> data(N);
    std::mt19937 rng(42);
    std::uniform_int_distribution<int> dist(0, 2147483647);

    for (int i = 0; i < N; ++i) data[i] = dist(rng);

    const int iterations = 10000;
    auto start_total = std::chrono::high_resolution_clock::now();

    for (int iter = 0; iter < iterations; ++iter) {
        for (int i = 0; i < N; ++i) data[i] = dist(rng);
        timsort(data, 0, N - 1);
    }

    auto end_total = std::chrono::high_resolution_clock::now();
    double total_ms = std::chrono::duration<double, std::milli>(end_total - start_total).count();
    double avg_us = (total_ms * 1000.0) / iterations;

    std::cout << "Timsort avg: " << avg_us << " µs\n";
    return 0;
}
