  open my $fh, ">", "test.html" or die;
  for my $i (1..1200000) {
    my $href = "https://example.com/page/" . int(rand(1000000));
    my $varspace = " " x (rand(5) + 1);
    print $fh "<a${varspace}href=\"$href\">Link $i</a>";
    print $fh "<p>Some random text with <b>tags</b> and <i>entities &amp; such</i><br>\n";
  }
  close $fh;
'
```

