size_t manual_parse(const char* data, size_t len, std::vector<size_t>& out) {
    size_t parsed = 0;
    for (size_t i = 0; i < len; ++i) {
        if (data[i] == ',') {
            parsed++;
            // In C++, we avoid allocation per element in tight loops
            out.push_back(parsed); 
        }
    }
    return parsed;
}

