```cpp
// parser.cpp
// Compile with: g++ -O3 -march=native -std=c++17 parser.cpp -o json_cpp_bench
// Requires: nlohmann/json via vcpkg or cmake: find_package(nlohmann_json 3.11 REQUIRED)

#include <nlohmann/json.hpp>
#include <fstream>
#include <iostream>
#include <chrono>
#include <string>
#include <vector>
#include <numeric>
#include <algorithm>

using json = nlohmann::json;

// Read entire file into memory once (fair comparison — both read from memory)
std::string load_json_file(const std::string& path) {
    std::ifstream file(path, std::ios::ate);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file: " + path);
    }
    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);
    std::string buffer(size, '\0');
    file.read(&buffer[0], size);
    return buffer;
}

// Validate parsed structure to prevent compiler optimizations from eliminating work
long long validate(const json& j) {
    long long sum = 0;
    if (j.is_array()) {
        for (const auto& item : j) {
            if (item.is_object()) {
                auto it_id = item.find("id");
                if (it_id != item.end() && it_id->is_number()) {
                    sum += *it_id;
                }
                auto it_name = item.find("name");
                if (it_name != item.end() && it_name->is_string()) {
                    sum += it_name->size();
                }
            }
        }
    }
    return sum;
}

int main() {
    const std::string filepath = "test_data.json";
    const int warmup_runs = 50;
    const int benchmark_runs = 500;

    try {
        std::cout << "Loading JSON data from " << filepath << "...\n";
        std::string json_str = load_json_file(filepath);
        std::cout << "Data size: " << json_str.size() << " bytes\n\n";

        // Warmup to stabilize caches and JIT/LTO effects
        std::cout << "Warmup (" << warmup_runs << " runs)...\n";
        for (int i = 0; i < warmup_runs; ++i) {
            json j = json::parse(json_str);
            validate(j);
        }

        // Benchmark
        std::cout << "Benchmark (" << benchmark_runs << " runs)...\n";
        std::vector<long long> times_us;
        times_us.reserve(benchmark_runs);

        long long checksum = 0;
        for (int i = 0; i < benchmark_runs; ++i) {
            auto start = std::chrono::high_resolution_clock::now();
            json j = json::parse(json_str);
            checksum += validate(j);
            auto end = std::chrono::high_resolution_clock::now();
            long long elapsed_us = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
            times_us.push_back(elapsed_us);
        }

        // Prevent dead-code elimination
        char sink[1024];
        std::memcpy(sink, &checksum, sizeof(checksum));

        // Statistics
        long long sum = 0;
        long long min_us = *std::min_element(times_us.begin(), times_us.end());
        long long max_us = *std::max_element(times_us.begin(), times_us.end());
        for (auto t : times_us) sum += t;
        long long mean_us = sum / times_us.size();

        std::sort(times_us.begin(), times_us.end());
        long long p50_us = times_us[times_us.size() / 2];
        long long p95_us = times_us[static_cast<size_t>(times_us.size() * 0.95)];
        long long p99_us = times_us[static_cast<size_t>(times_us.size() * 0.99)];

        std::cout << "\n=== C++ (nlohmann/json) Results ===\n";
        std::cout << "Mean:      " << mean_us << " µs\n";
        std::cout << "Median:    " << p50_us << " µs\n";
        std::cout << "P95:       " << p95_us << " µs\n";
        std::cout << "P99:       " << p99_us << " µs\n";
        std::cout << "Min:       " << min_us << " µs\n";
        std::cout << "Max:       " << max_us << " µs\n";
        std::cout << "Std Dev:   " << std::sqrt(std::accumulate(times_us.begin(), times_us.end(), 0.0,
            [&](double acc, long long t) { return acc + std::pow(t - mean_us, 2); }) / times_us.size()) << " µs\n";
        std::cout << "Parse rate: " << (1000000.0 * benchmark_runs) / sum << " MB/sec (10MB payload)\n";
        std::cout << "\nChecksum (anti-optimization): " << checksum << "\n";

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }
    return 0;
}
