        int count = 0;
        for (int i = 0; i < _data.Length; i++)
            if (_data[i] > 0) count++;

        var result = new int[count];
        int idx = 0;
        for (int i = 0; i < _data.Length; i++)
            if (_data[i] > 0) result[idx++] = _data[i];

        return result;
    }

    // ──────────────────────────────────────────────
    // 3. LINQ .Where().ToList()
    // ──────────────────────────────────────────────
