var errors = lines
    .SelectMany(l => Regex.Matches(l, pattern))
    .Where(m => m.Success)
    .Select(m => ParseError(m.Value))
    .ToList();

// ✅ Do this instead for large collections:
var results = new List<Error>(estimatedCapacity);
foreach (var line in lines)
{
    if (TryParseError(line, out var err))
        results.Add(err);
}
```

## Best Practices for .NET 8+

### 1. Use `Span<T>` / `Memory<T>` for Zero-Allocation Sweeps
```csharp
// .NET 8+, zero-allocation, fastest option:
var buffer = new Span<int>(_data);
int count = 0;
foreach (var x in buffer)
    if (x > 0) count++;

var result = new ValueArray<int>(count);  // or pre-allocated pool
int idx = 0;
foreach (var x in buffer)
    if (x > 0) result[idx++] = x;
```

### 2. Let .NET 8's `List<T>.Span` Help
```csharp
var list = new List<int>(estimatedCapacity);
ref var span = ref list;  // pin the list's internal array
// Manual indexing into the underlying storage
```

### 3. Parallelize When Possible
```csharp
// Parallel LINQ (PLinq) can close the gap:
var result = _data
    .AsParallel()
    .AsUnordered()
    .Where(x => x > 0)
    .ToList();
// ~2–4x faster on multi-core, but still slower than parallelized for-loops
```

```csharp
// Better: Parallel.For with local aggregates
var segments = new List<int>[Environment.ProcessorCount];
Parallel.For(0, Environment.ProcessorCount, (idx, state, localObj) =>
{
    var localList = new List<int>();
    int start = idx * (_data.Length / segments.Length);
    int end = idx == segments.Length - 1 ? _data.Length : start + (_data.Length / segments.Length);
    for (int i = start; i < end; i++)
        if (_data[i] > 0) localList.Add(_data[i]);
    segments[idx] = localList;
});
// Merge local aggregates
var finalResult = segments.SelectMany(l => l).ToArray();
```

## Decision Matrix

```
Is the collection small (<100K) and not in a hot path?
├── Yes → Use LINQ for readability. The overhead is negligible.
└── No
    └── Is the code in a performance-critical path?
        ├── Yes → Use `for` loop with pre-sized allocation.
