### Go Implementation (`go_main.go`)
```go
package main

import (
	"encoding/json"
	"fmt"
	"strings"
	"time"
)

type Payload struct {
	Name   string `json:"name"`
	Value  int    `json:"value"`
	Active bool   `json:"active"`
}

func main() {
	var raw = `{"name":"Example Data","value":12345,"active":true}`
	var buf = strings.NewReader(raw)
	var iterations = 1000000

	start := time.Now()

	// Pre-allocate buffer for pooling
	bufPool := make(chan []byte, 1)
	bufPool <- make([]byte, 0, 1024)

	for i := 0; i < iterations; i++ {
		// Reset reader position
		buf.Seek(0, 0)
		var p Payload
		// Use a local decoder to simulate raw performance of the package
		dec := json.NewDecoder(buf)
		_ = dec.Decode(&p)
	}

	stop := time.Now()
	elapsed := stop.Sub(start)

	fmt.Printf("Go (encoding/json): %v for %d iterations. Avg: %v\n", elapsed, iterations, elapsed/time.Duration(iterations))
	_ = buf
}
```

