# High-Performance JSON Parsing: Go vs C++ — A Benchmark-Driven Comparison

## The Methodology

To keep this fair and meaningful, I'm implementing **minimalist, high-performance JSON parsers** in both languages that parse a JSON object and extract `int64` values by field name. No heavy libraries, no reflection-based generic parsers—just raw parsing logic optimized for speed.

**Test JSON** (repeating pattern for realistic data):
```json
{"id":1,"name":"alice","score":95,"id":2,"name":"bob","score":87,...}
```

**Metric:** Mean time to parse 1MB of JSON, extracted via `time` command + internal wall-clock validation.

---

## Go Implementation

```go
// jsonparser_go.go
package main

import (
	"fmt"
	"os"
	"time"
)

// Minimalist high-performance JSON parser
// Parses JSON of the form: {"key":value,"key":value,...}
// Extracts int64 values for specified keys.
func parseJSON(json []byte, keys []string) map[string]int64 {
	result := make(map[string]int64)

	// Track which keys we're looking for for fast lookup
	keySet := make(map[string]bool)
	for _, k := range keys {
		keySet[k] = true
	}

	i := 0
	n := len(json)

	// Skip opening brace
	if i < n && json[i] == '{' {
		i++
	}

	for i < n {
		// Skip whitespace
		for i < n && (json[i] == ' ' || json[i] == '\n' || json[i] == '\r' || json[i] == '\t') {
			i++
		}
		if i >= n || json[i] == '}' {
			break
		}

		// Expect a quoted string key
		if json[i] == '"' {
			i++ // skip opening quote
			keyStart := i
			for i < n && json[i] != '"' {
				i++
			}
			if i >= n {
				break
			}
			key := string(json[keyStart:i])
			i++ // skip closing quote

			// Skip whitespace and colon
			for i < n && (json[i] == ' ' || json[i] == '\n' || json[i] == '\r' || json[i] == '\t') {
				i++
			}
			if i < n && json[i] == ':' {
				i++
			}
			for i < n && (json[i] == ' ' || json[i] == '\n' || json[i] == '\r' || json[i] == '\t') {
				i++
			}

			if keySet[key] {
				// Parse the value (handle int, string, etc.)
				if i < n {
					if json[i] == '"' {
						// String value — skip it
						i++
						for i < n && json[i] != '"' {
							i++
						}
						if i < n {
							i++
						}
					} else if json[i] == '-' || (json[i] >= '0' && json[i] <= '9') {
						// Integer value
						numStart := i
						if json[i] == '-' {
							i++
						}
						for i < n && json[i] >= '0' && json[i] <= '9' {
							i++
						}
						var val int64
						for j := numStart; j < i; j++ {
							if json[j] == '-' {
								continue
							}
							val = val*10 + int64(json[j]-'0')
						}
						result[key] = val
					} else if json[i] == 't' || json[i] == 'f' || json[i] == 'n' {
						// Skip true/false/null
						if json[i] == 't' || json[i] == 'f' {
							i += 4 // true/false
						} else if json[i] == 'n' {
							i += 4 // null
						}
					} else if json[i] == '[' {
						// Skip array (simplified — doesn't handle nesting recursively)
						depth := 1
						i++
						for i < n && depth > 0 {
							if json[i] == '[' {
								depth++
							} else if json[i] == ']' {
								depth--
							}
							i++
						}
					} else if json[i] == '{' {
						// Skip object (simplified)
						depth := 1
						i++
						for i < n && depth > 0 {
							if json[i] == '{' {
								depth++
							} else if json[i] == '}' {
								depth--
							} else if json[i] == '"' {
								i++
								for i < n && json[i] != '"' {
									i++
								}
							}
							i++
						}
					}
				}
			} else {
				// Skip value entirely
				skipValue := func() {
					if i < n {
						if json[i] == '"' {
							i++
							for i < n && json[i] != '"' {
								if json[i] == '\\' {
									i++ // skip escaped char
								}
								i++
							}
							if i < n {
								i++
							}
						} else if json[i] == '-' || (json[i] >= '0' && json[i] <= '9') {
							for i < n && json[i] >= '0' && json[i] <= '9' {
								i++
							}
						} else if json[i] == 't' || json[i] == 'f' {
							i += 4
						} else if json[i] == 'n' {
							i += 4
						} else if json[i] == '[' {
							depth := 1
							i++
							for i < n && depth > 0 {
								if json[i] == '[' {
									depth++
								} else if json[i] == ']' {
									depth--
								} else if json[i] == '"' {
									i++
									for i < n && json[i] != '"' {
										i++
									}
								}
								i++
							}
						} else if json[i] == '{' {
							depth := 1
							i++
							for i < n && depth > 0 {
								if json[i] == '{' {
									depth++
								} else if json[i] == '}' {
									depth--
								} else if json[i] == '"' {
									i++
									for i < n && json[i] != '"' {
										i++
									}
								}
								i++
							}
						} else {
							i++
						}
					}
				}
				skipValue()
			}
		} else {
			i++
		}

		// Skip comma
		for i < n && (json[i] == ' ' || json[i] == '\n' || json[i] == '\r' || json[i] == '\t') {
			i++
		}
		if i < n && json[i] == ',' {
			i++
