    for (int k : keys) avl.insert(k);
    rng.shuffle(keys);
    for (int k : keys) avl.remove(k);
    auto t2 = chrono::high_resolution_clock::now();
    auto avl_time = chrono::duration_cast<chrono::microseconds>(t2 - t1);

    // --- Benchmark Red-Black (std::set) ---
    auto t3 = chrono::high_resolution_clock::now();
    set<int> rbt;
    rng.shuffle(keys);
