    qq{<a href="http://example.com/link$_" class="foo" title="bar">Link $_</a>}
} 1..50000;

cmpthese(-10, {
    'regex_old'  => sub { my @l = $html =~ /<a\s+[^>]*href="([^"]*)"[^>]*>/g; },
    'regex_new'  => sub { my @l = $html =~ /<a\s[^>]*?\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|(\S+))\s*[^>]*?>/g; },
