using BenchmarkDotNet.Running;

[ShortRunJob] // Good for measuring JIT overhead
public class JitOverheadBenchmark
{
    private readonly MyService _service = new();

    [Benchmark]
    public void FirstCall()
    {
        _service.DoComplexWork();
    }

    [Benchmark]
    public void WarmCall()
    {
        // Warm up first
        _service.DoComplexWork();
        // Then measure
        _service.DoComplexWork();
    }
}

public class MyService
{
    public void DoComplexWork()
    {
        // Your moderately complex logic here
        var sum = 0;
        for (int i = 0; i < 1000; i++)
        {
            sum += i * 2;
        }
    }
}

// Run it:
// BenchmarkRunner.Run<JitOverheadBenchmark>();
```

### Key Takeaway
For a moderately complex method, expect a **one-time cost of ~20–50 µs**. If your operation has a budget of milliseconds, this is negligible. If you’re optimizing for nanosecond-scale latency (e.g., high-frequency trading), you’ll need to warm up all paths during initialization or use Native AOT.

