I understand your skepticism about marketing claims. Let me implement practical, high-performance JSON parsing in both languages and provide actual benchmark data. I'll use realistic benchmarking with large, nested JSON payloads to reflect real-world data processing scenarios.

## C++ Implementation (Using rapidjson)

```cpp
// cpp_bench.cpp
// Requires: rapidjson (g++ cpp_bench.cpp -O2 -o cpp_bench -std=c++17)

#include <rapidjson/rapidjson.h>
#include <rapidjson/document.h>
#include <rapidjson/stringbuffer.h>
#include <rapidjson/writer.h>
#include <fstream>
#include <string>
#include <chrono>
#include <vector>
#include <iostream>
#include <numeric>

// Read entire file into string
std::string read_file(const std::string& path) {
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    if (!f) {
        std::perror("Failed to open file");
        exit(1);
    }
    std::streamsize size = f.tellg();
    f.seekg(0, std::ios::beg);
    std::string contents(static_cast<size_t>(size), '\0');
    f.read(&contents[0], size);
    return contents;
}

// Benchmark rapidjson parsing
double parse_rapidjson(const std::string& json, int iterations) {
    auto start = std::chrono::high_resolution_clock::now();
    ::rapidjson::Document doc;
    ::rapidjson::Document::ParseResult ok;

    for (int i = 0; i < iterations; ++i) {
        doc.SetString();  // Reset doc
        ok = doc.Parse(json.c_str());
        if (!ok) {
            std::cerr << "Parse error at offset: " << doc.GetErrorOffset() << std::endl;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);
    return duration.count() / iterations; // avg microseconds per parse
}

int main() {
    std::string json = read_file("test_data.json");
    std::cout << "JSON size: " << json.size() << " bytes" << std::endl;

    // Warmup
    parse_rapidjson(json, 100);

    // Benchmark
    int iterations = 1000;
    double avg_us = parse_rapidjson(json, iterations);

    std::cout << "C++ (rapidjson) - " << iterations << " iterations" << std::endl;
    std::cout << "Average time: " << avg_us << " μs per parse" << std::endl;
    std::cout << "Throughput: " << (1e6 / avg_us) << " parses/sec" << std::endl;

    return 0;
}
```

## Go Implementation

```go
// go_bench.go
// Run with: go build -o go_bench go_bench.go && ./go_bench

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"time"
)

// Unmarshals JSON into a generic interface{} to match C++'s Document behavior
func benchmark_json_unmarshal(data []byte, iterations int) float64 {
	var result interface{}

	start := time.Now()
	for i := 0; i < iterations; i++ {
		err := json.Unmarshal(data, &result)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Unmarshal error: %v\n", err)
			os.Exit(1)
		}
	}
	elapsed := time.Since(start)

	return float64(elapsed) / float64(iterations) / float64(time.Microsecond)
}

// Pre-allocate result to reduce allocations
type ParsedData struct {
	ID    int             `json:"id"`
	Name  string          `json:"name"`
	Nested map[string]interface{} `json:"nested"`
	Array  []interface{}   `json:"array"`
}

func benchmark_typed_unmarshal(data []byte, iterations int) float64 {
	var result ParsedData

	// Reset to a zero value before each iteration to avoid stale data issues
	zero := ParsedData{}

	start := time.Now()
	for i := 0; i < iterations; i++ {
		// We need to re-parse; Go doesn't have a reset like rapidjson
		// Using a new variable each iteration to ensure clean state
		var res ParsedData
		err := json.Unmarshal(data, &res)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Unmarshal error: %v\n", err)
			os.Exit(1)
		}
		result = res // Keep to prevent compiler optimization
	}
	elapsed := time.Since(start)

	return float64(elapsed) / float64(iterations) / float64(time.Microsecond)
}

func main() {
	data, err := os.ReadFile("test_data.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to read file: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("JSON size: %d bytes\n", len(data))

	iterations := 1000

	// Warmup
	_ = benchmark_json_unmarshal(data, 100)
	_ = benchmark_typed_unmarshal(data, 100)

	// Benchmark generic
	avgGeneric := benchmark_json_unmarshal(data, iterations)
	fmt.Printf("Go (generic interface{}) - %d iterations\n", iterations)
	fmt.Printf("Average time: %.2f μs per parse\n", avgGeneric)
	fmt.Printf("Throughput: %.0f parses/sec\n\n", 1e6/avgGeneric)

	// Benchmark typed
	avgTyped := benchmark_typed_unmarshal(data, iterations)
	fmt.Printf("Go (typed struct) - %d iterations\n", iterations)
	fmt.Printf("Average time: %.2f μs per parse\n", avgTyped)
	fmt.Printf("Throughput: %.0f parses/sec\n", 1e6/avgTyped)
}
