### 1. The C++ Implementation (Using `simdjson`)
`simdjson` is currently the fastest JSON parser in existence. It processes thousands of bytes per clock cycle using SIMD instructions. It avoids most allocations by returning pointers into the original buffer.

```cpp
// main.cpp
#include <iostream>
#include <chrono>
#include <simdjson.h>
#include <vector>
#include <iomanip>

// Simulated "heavy" JSON payload (approx 1KB)
const std::string paylod_template = R"({
    "id": %d,
    "timestamp": %d,
    "username": "user_%d_active_session_data_string_with_variable_length",
    "metadata": {
        "tags": ["tag1", "tag2", "tag3"],
        "score": 0.95,
        "active": true
    },
    "nested": {
        "data": [10, 20, 30, 40, 50],
        "status": "ok",
        "errors": []
    }
})";

std::vector<std::string> generate_payloads(int growth_factor) {
    std::vector<std::string> payloads;
    payloads.reserve(growth_factor);
    for (int i = 0; i < growth_factor; ++i) {
        int ts = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        payloads.push_back((fmt::format(paylod_template, i, ts, i)));
    }
    return payloads;
}

int main() {
    const int NUM_RUNS = 1000000; // 1 Million parses
    const int NUM_ITEMS = 10;     // Batch size to keep buffer manageable

    std::cout << "Generating payloads..." << std::endl;
    std::vector<std::string> payloads = generate_payloads(NUM_ITEMS);
    int total_payloads = NUM_RUNS * NUM_ITEMS;

    simdjson::dom::parser parser;

    // Warmup
    for (int i = 0; i < 1000; ++i) {
        auto doc = parser.parse(payloads[i % NUM_ITEMS]);
    }

    auto start = std::chrono::high_resolution_clock::now();

    // Benchmark Loop
    for (int i = 0; i < NUM_RUNS; ++i) {
        for (int j = 0; j < NUM_ITEMS; ++j) {
            simdjson::dom::element doc;
            // Zero-allocation parse: doc points into payloads buffer
            auto error = parser.parse(payloads[j].c_str(), payloads[j].size()).get(doc);
            if (error) {
                std::cerr << "Parse error: " << error.message() << "\n";
                return 1;
            }

            // Verify data access (forces CPU to read fields)
            auto id = doc["id"].get_int64().value();
            auto active = doc["metadata"]["active"].get_bool().value();
            auto score = doc["metadata"]["score"].get_double().value();

            // volatile to prevent compiler optimization of unused variables
            volatile long long vid = id;
            volatile bool v_active = active;
            volatile double v_score = score;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> elapsed = end - start;

    double seconds = elapsed.count() / 1000.0;
    double ms_per_parse = (elapsed.count() / total_payloads);
    double parses_per_sec = total_payloads / seconds;
    double mb_per_sec = (total_payloads * payloads[0].size()) / (1024.0 * 1024.0) / seconds;

    std::cout << "\n=== C++ simdjson Benchmark ===" << std::endl;
    std::cout << "Total Parses: " << total_payloads << std::endl;
    std::cout << "Total Time:   " << std::fixed << std::setprecision(2) << seconds << " s" << std::endl;
    std::cout << "Parses/sec:   " << std::fixed << std::setprecision(0) << parses_per_sec << std::endl;
    std::cout << "MB/sec:       " << std::fixed << std::setprecision(2) << mb_per_sec << std::endl;
    std::cout << "Avg ms/parse: " << std::fixed << std::setprecision(4) << ms_per_parse << std::endl;

    return 0;
}
```

