### 🚀 C++ Implementation

We’ll use two libraries:
1. **`nlohmann/json`**: Easy to use, moderate speed.
2. **`simdjson`**: The state-of-the-art fast JSON parser, using SIMD instructions.

```cpp
// main.cpp
#include <nlohmann/json.hpp>
#include <simdjson.h>
#include <iostream>
#include <fstream>
#include <chrono>
#include <string>

using nlohmann::json;

std::string loadFile(const std::string& filename) {
    std::ifstream file(filename);
    return std::string((std::istreambuf_iterator<char>(file)),
                       std::istreambuf_iterator<char>());
}

int main() {
    std::string filepath = "large.json";
    std::string json_str = loadFile(filepath);
    size_t len = json_str.size();

    // Benchmark nlohmann/json
    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 100; ++i) {
        json j = json::parse(json_str);
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> elapsed_nlohmann = end - start;
    std::cout << "nlohmann/json: " << elapsed_nlohmann.count() / 100 << " ms per parse\n";

    // Benchmark simdjson
    simdjson::ondemand::parser parser;
    start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 100; ++i) {
        auto doc = parser.iterate(reinterpret_cast<const uint8_t*>(json_str.c_str()), len);
        // Force evaluation by iterating the root object
        for (auto [key, value] : doc) {
            if (key.value() == "ignore_key") { /* just to force evaluation */ }
        }
    }
    end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> elapsed_simdjson = end - start;
    std::cout << "simdjson: " << elapsed_simdjson.count() / 100 << " ms per parse\n";

    return 0;
}
```

