using System.Runtime.CompilerServices;

public class ColdStartBenchmark
{
    private readonly ComplexService _service = new();

    // This method represents your "moderately complex" logic
    public double CalculateComplexValue(int seed)
    {
        double result = 0;
        for (int i = 0; i < 1000; i++)
        {
            result += Math.Sqrt(i + seed) * Math.Sin(i);
            // Add some branching/object creation if needed
