        GC.Collect();
        GC.WaitForPendingFinalizers();

        // Warmup: JIT compile irrelevant methods to isolate
        GC.Collect();

        // Method 1: First-call (Cold) measurement
        var swCold = Stopwatch.StartNew();
        double coldResult = _service.CalculateComplexValue(42);
        swCold.Stop();

        // Method 2: Warm measurement (average of 100 calls)
        var swWarm = Stopwatch.StartNew();
