        double avgWarm = swWarm.ElapsedTicks / 100.0;

        Console.WriteLine($"Cold Call Duration: {swCold.ElapsedTicks} ticks");
        Console.WriteLine($"Avg Warm Call Duration: {avgWarm} ticks");
        Console.WriteLine($"Overhead: {swCold.ElapsedTicks - avgWarm} ticks");
    }
