### 2. C++ Implementation (RapidJSON)

*Prerequisite: You must include RapidJSON (`#include "rapidjson/document.h"` etc.). It is a header-only library.*

```cpp
#include <iostream>
#include <chrono>
#include <string>
#include "rapidjson/document.h"
#include "rapidjson/memorystream.h"

// Define a parallel class or structure to hold parsed data
struct LogEntry {
    int id;
    std::string name;
    bool active;
    double score;
    // For simplicity, we'll just validate presence and extract key fields.
    // RapidJSON avoids copying strings if we use StringRefs, but to be fair 
    // and safe, we'll mimic Go's structural extraction.
};

// Helper to parse manually to struct to match Go's semantics
LogEntry parseJson(const rapidjson::Document& doc) {
    LogEntry entry;
    if (doc.HasMember("id")) entry.id = doc["id"].GetInt();
    if (doc.HasMember("name")) entry.name = doc["name"].GetString(); // Copies string
    if (doc.HasMember("active")) entry.active = doc["active"].GetBool();
    if (doc.HasMember("score")) entry.score = doc["score"].GetDouble();
    return entry;
}

int main() {
    const char* jsonStr = R"({
        "id": 12345,
        "name": "Alice",
        "active": true,
        "score": 98.76,
        "tags": ["admin", "user"],
        "meta": {
            "created": "2023-10-01",
            "source": "api"
        }
    })";

    const size_t iterations = 10000000;

    // Pre-parse to warm up allocations/cache
    rapidjson::Document doc;
    doc.Parse(jsonStr);

    auto start = std::chrono::high_resolution_clock::now();

    for (size_t i = 0; i < iterations; ++i) {
        // RapidJSON requires a new Document or Reset. 
        // Creating a new Document is the standard "safe" way.
        rapidjson::Document d;
        d.Parse(jsonStr);
        LogEntry e = parseJson(d);
        // Prevent compiler optimization of unused variable
        if (e.name.empty()) { /* noop */ }
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> duration = end - start;

    std::cout << "C++ (RapidJSON): " << duration.count() << " ms for 10M parses" << std::endl;
    std::cout << "C++: " << (duration.count() * 1000.0 / iterations) << " us per parse" << std::endl;
    return 0;
}
```

