## 1. High-Performance C++ Implementation
We’ll use a hand-optimized, non-recursive, zero-allocation JSON parser that parses directly into a static parse tree. No `std::string` allocations for keys/values; we use offset/length pairs into the original JSON buffer.

```cpp
// cpp_vinaigrette/json_parser.cpp
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <stdexcept>

// Simpler, faster than nlohmann/stiff for pure speed
// Returns a flat array of values with type tags

enum JsonType {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
};

struct JsonValue {
    uint8_t type;
    int32_t value_offset;    // For strings: offset into source, for numbers: offset
    int32_t value_length;    // For strings: length, for numbers: ~unused
    int32_t array_length;    // For arrays: number of elements
    int32_t object_length;   // For objects: number of key-value pairs
    int32_t first_child_idx; // Index into the flat values array
};

// Internal buffer for parse tree
constexpr size_t MAX_NESTING_DEPTH = 128;
constexpr size_t MAX_VALUES = 10000;

struct ParserState {
    const char* input;
    size_t input_len;
    size_t pos;
    JsonValue values[MAX_VALUES];
    int value_count;
    int child_stack[MAX_NESTING_DEPTH];
    int stack_top;
};

static inline void skip_whitespace(ParserState& s) {
    while (s.pos < s.input_len && (s.input[s.pos] == ' ' || s.input[s.pos] == '\t' || 
           s.input[s.pos] == '\n' || s.input[s.pos] == '\r')) {
        s.pos++;
    }
}

static inline void skip_quoted_string(ParserState& s) {
    s.pos++; // skip opening "
    bool escaped = false;
    while (s.pos < s.input_len) {
        char c = s.input[s.pos];
        if (escaped) {
            escaped = false;
        } else if (c == '\\') {
            escaped = true;
        } else if (c == '"') {
            s.pos++;
            return;
        }
        s.pos++;
    }
    throw std::runtime_error("Unterminated string");
}

static inline JsonValue& push_value(ParserState& s, JsonType type, int first_child = -1) {
    JsonValue& v = s.values[s.value_count++];
    v.type = type;
    v.first_child_idx = first_child;
    v.array_length = 0;
    v.object_length = 0;
    v.value_offset = 0;
    v.value_length = 0;
    return v;
}

// Parse a single value
static inline void parse_value(ParserState& s) {
    skip_whitespace(s);
    if (s.pos >= s.input_len) throw std::runtime_error("Unexpected end");

    char c = s.input[s.pos];
    if (c == '{') {
        parse_object(s);
    } else if (c == '[') {
        parse_array(s);
    } else if (c == '"') {
        parse_string(s);
    } else if (c == 't' || c == 'f') {
        parse_bool(s);
    } else if (c == 'n') {
        parse_null(s);
    } else if (c == '-' || (c >= '0' && c <= '9')) {
        parse_number(s);
    } else {
        throw std::runtime_error(std::string("Unexpected char: ") + c);
    }
}

// ... [Helper functions for object, array, string, number, bool, null omitted for brevity but follow same pointer-chasing logic] ...

// For real use, see full implementation below in benchmark harness
