use strict;
use warnings;
use File::Slurp qw(read_file write_file);

$| = 1;
my $N = 1_000_000; # 1 million links
my $html = "<html><body>\n";
for my $i (1..$N) {
    # Mix attribute orders and quote styles to stress-test
    my $type = int(rand(3));
    if ($type == 0) {
        $html .= "<a href=\"http://example.com/$i\" class=\"link\">Link $i</a>\n";
    } elsif ($type == 1) {
        $html .= "<a class=\"redirect\" href=\"http://example.com/$i\">Link $i</a>\n";
    } else {
        $html .= "<a href='http://example.org/$i' title=\"Title\">Link $i</a>\n";
    }
}
$html .= "</body></html>";
