// matmul.cpp
extern "C" {
    void matmul(const double* A, const double* B, double* C, int N) {
        for (int i = 0; i < N; i++)
            for (int k = 0; k < N; k++) {
                double a_ik = A[i * N + k];
                for (int j = 0; j < N; j++)
                    C[i * N + j] += a_ik * B[k * N + j];
            }
