#include <vector>
#include <chrono>
#include <cstdint>

// A simplified structure to hold parsed key-value pairs
struct JsonEntry {
    const char* key;
    const char* value;
};

// A basic "destructive" allocator that returns memory from a pre-allocated pool
// to minimize fragmentation and allocator overhead.
class ScratchBuffer {
public:
    std::vector<char> data;
    size_t offset = 0;

    ScratchBuffer(size_t size) : data(size) {}

    void reset() { offset = 0; }

    const char* take_string(const char* start, size_t len) {
        if (offset + len > data.size()) return nullptr;
        memcpy(&data[offset], start, len); // Null-terminate or store length separately
        offset += len;
        return &data[offset - len];
    }
};

// A representative "parser" that iterates over a character array.
// In a real-world scenario, this would follow RFC 8259.
bool parse_json_fast(const char* input, size_t len, ScratchBuffer& buf, std::vector<JsonEntry>& out) {
    buf.reset();
    out.clear();
    const char* p = input;
    const char* end = input + len;

    while (p < end) {
        if (*p != '"') { p++; continue; } // Skip to next quote
        const char* key_start = p + 1;
        while (p < end && *p != '"') p++;
        if (p >= end) return false;
        size_t key_len = p - key_start;

        // Expect colon
        while (p < end && (*p == ' ' || *p == ':' || *p == '\n')) p++;

        // Expect value (simplified string value)
        if (*p == '"') {
            const char* val_start = p + 1;
            while (p < end && *p != '"') p++;
            if (p >= end) return false;
            size_t val_len = p - val_start;

            out.push_back({
                buf.take_string(key_start, key_len),
                buf.take_string(val_start, val_len)
            });
        }
        p++;
    }
    return true;
}

int main() {
    // Generate a representative JSON payload
    std::string payload = "{";
    for (int i = 0; i < 1000; ++i) {
        payload += "\"key" + std::to_string(i) + "\":\"value" + std::to_string(i) + "\",";
    }
    payload[0] = '{'; payload[0] = ','; payload.back() = '}';

    ScratchBuffer buf(1024 * 1024); // 1MB pool
    std::vector<JsonEntry> results;

    auto start = std::chrono::high_resolution_clock::now();
    for (int i = 0; i < 10000; ++i) {
        parse_json_fast(payload.c_str(), payload.size(), buf, results);
    }
    auto end = std::chrono::high_resolution_clock::now();

    std::cout << "C++ Time: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";
    return 0;
}
```

### Go Implementation (Standard Reflection-based)

Go's standard library `encoding/json` is robust and type-safe. However, its internal use of `reflect` to map bytes to exported struct fields introduces a "reflection tax." This is the primary bottleneck when compared to a zero-allocation C++ parser.

```go
