#### C++ Implementation (Using `simdjson`)
`simdjson` is currently the fastest JSON parser in the world, using single-instruction-multiple-data (SIMD) instructions and a dom-tree parsing approach. It ignores validation errors for speed (by default) and is written in highly optimized C++.

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <chrono>
#include "simdjson.h"

using namespace simdjson;

int main() {
    // Load JSON file into memory
    std::ifstream file("large_payload.json");
    std::string json_str((std::istreambuf_iterator<char>(file)),
                         std::istreambuf_iterator<char>());
    std::vector<char8_t> json_buffer(json_str.begin(), json_str.end());

    padded_string json_input(json_buffer.data(), json_buffer.size());

    // Initialize parser
    ondemand::parser parser;

    // Warm-up run
    auto it = parser.iterate(json_input);
    auto root = it.get<object>();
    for(auto element : root) {} 

    // Benchmark
    const int ITERATIONS = 100;
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < ITERATIONS; ++i) {
        try {
            ondemand::document doc = parser.iterate(json_input);
            auto root = doc.get<object>();
            volatile int dummy = 0; // Prevent optimization
            for(auto element : root) {
                dummy++;
            }
        } catch(simdjson::simdjson_error& e) {
            std::cerr << e.what() << std::endl;
            return 1;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::micro> elapsed = end - start;

    double mb_s = (json_buffer.size() / 1024.0 / 1024.0) * ITERATIONS / (elapsed.count() / 1000000.0);

    std::cout << "C++ (simdjson) Avg Time: " << elapsed.count() / ITERATIONS << " µs\n";
    std::cout << "Throughput: " << mb_s << " MB/s\n";

    return 0;
}
```

