};

// Fast skip function (avoids string creation)
const char* skip_string(const char* p, std::string& out) {
    if (*p != '"') return nullptr;
    p++;
    size_t start = p - payload.data(); // In real code, use pointers
    while (*p != '"' && *p != '\0') {
        if (*p == '\\') { p++; } // Simplified escape handling
        p++;
    }
    if (*p == '"') {
        out.assign(payload.data() + start, p - (payload.data() + start));
        p++;
    }
    return p;
}

// Fast numeric parser
const char* parse_number(const char* p, int& val) {
    val = 0;
    while (isdigit(*p)) {
        val = val * 10 + (*p - '0');
        p++;
    }
    return p;
}

const char* parse_double(const char* p, double& val) {
    // Use strtod for simplicity in demo, but custom parser is faster
    char* end;
    val = strtod(p, &end);
    return end;
}

// Payload is a global raw byte array for testing
std::string payload;

// The core parsing function
bool parse_json(const char* data, User& user) {
    const char* p = data;
    if (*p++ != '{') return false;

    while (*p != '\0' && *p != '}') {
        if (*p == ',' || *p == ' ') { p++; continue; }
        if (*p == '{') return true; // Reached end of object

        // Parse key
        std::string key;
        p = skip_string(p, key);
        p++; // skip ':'

        if (key == "name") {
            p = skip_string(p, user.name);
        } else if (key == "age") {
            while (isspace(*p)) p++;
            p = parse_number(p, user.age);
        } else if (key == "score") {
            while (isspace(*p)) p++;
            p = parse_double(p, user.score);
        } else if (key == "tags") {
            if (*p == '[') {
                p++;
                while (*p != ']') {
                    std::string tag;
                    if (*p == ',') p++;
                    p = skip_string(p, tag);
                    user.tags.push_back(tag);
                }
                p++;
            }
        }
    }
    return true;
}

