### 1. C++ Implementation (using `simdjson`)

`simdjson` uses SIMD (Single Instruction, Multiple Data) instructions to scan JSON bytes in parallel. It is orders of magnitude faster than `nlohmann/json` or `rapidjson` for large structures.

**File: `parser_simd.cpp`**
```cpp
#include <iostream>
#include <string>
#include "simdjson.h"

using namespace simdjson;

// Function to parse and sum a specific field to prevent compiler optimizations
double parse_and_sum(on_demand::parser &parser, on_demand::document &doc, const on_demand::object &loc) {
    if (!loc) return 0.0;

    double sum = 0.0;
    on_demand::object loc_obj = document["location"]; // Example: { "lat": 40.7, "lng": -74.0 }

    if (loc_obj) {
        double lat = loc_obj["lat"];
        double lng = loc_obj["lng"];
        if (lat && lng) {
            sum = lat + lng;
        }
    }
    return sum;
}

extern "C" double parse_and_process_cxx(const char* json, size_t len) {
    on_demand::parser parser;
    on_demand::document doc = parser.iterate(json, len);
    on_demand::object root = doc["root"];
    return parse_and_sum(parser, doc, root);
}
```

