### Empirical Benchmark Setup
*   **Operations**: 7,151 Inserts + 7,151 Deletes = 14,302 total.
*   **Data**: Integers $0 \dots 14,301$, inserted in random order, deleted in random order.
*   **Compiler**: GCC 13 with `-O3`.
*   **Metric**: Wall-clock time for the operation loop.

Here is the C++ benchmark code using `std::map` (RBTree) and a custom AVL implementation:

```cpp
#include <iostream>
#include <chrono>
#include <vector>
#include <random>
#include <algorithm>
#include <map> // Red-Black Tree

// Simple Node-Based AVL Implementation for comparison
template<typename T>
struct AVLNode {
    T key;
    int height;
    AVLNode* left;
    AVLNode* right;
    AVLNode(T k) : key(k), height(1), left(nullptr), right(nullptr) {}
};

class AVLOneInsertDelete {
    AVLNode<int>* root = nullptr;

    int getHeight(AVLNode<int>* n) { return n ? n->height : 0; }
    int getBalance(AVLNode<int>* n) { return n ? getHeight(n->left) - getHeight(n->right) : 0; }

    AVLNode<int>* rightRotate(AVLNode<int>* y) {
        AVLNode<int>* x = y->left;
        AVLNode<int>* T2 = x->right;
        x->right = y;
        y->left = T2;
        y->height = std::max(getHeight(y->left), getHeight(y->right)) + 1;
        x->height = std::max(getHeight(x->left), getHeight(x->right)) + 1;
        return x;
    }

    AVLNode<int>* leftRotate(AVLNode<int>* x) {
        AVLNode<int>* y = x->right;
        AVLNode<int>* T2 = y->left;
        y->left = x;
        x->right = T2;
        x->height = std::max(getHeight(x->left), getHeight(x->right)) + 1;
        y->height = std::max(getHeight(y->left), getHeight(y->right)) + 1;
        return y;
    }

    AVLNode<int>* insert(AVLNode<int>* node, int key) {
        if (!node) return new AVLNode<int>(key);
        if (key < node->key) node->left = insert(node->left, key);
        else if (key > node->key) node->right = insert(node->right, key);
        else return node; // No duplicates

        node->height = 1 + std::max(getHeight(node->left), getHeight(node->right));
        int balance = getBalance(node);

        // Left Left
        if (balance > 1 && key < node->left->key)
            return rightRotate(node);
        // Right Right
        if (balance < -1 && key > node->right->key)
            return leftRotate(node);
        // Left Right
        if (balance > 1 && key > node->left->key) {
            node->left = leftRotate(node->left);
            return rightRotate(node);
        }
        // Right Left
        if (balance < -1 && key < node->right->key) {
            node->right = rightRotate(node->right);
            return leftRotate(node);
        }
        return node;
    }

    AVLNode<int>* minValueNode(AVLNode<int>* node) {
        AVLNode<int>* current = node;
        while (current->left != nullptr)
            current = current->left;
        return current;
    }

    AVLNode<int>* deleteNode(AVLNode<int>* node, int key) {
        if (!node) return node;
        if (key < node->key) node->left = deleteNode(node->left, key);
        else if (key > node->key) node->right = deleteNode(node->right, key);
        else {
            if (!node->left || !node->right) {
                AVLNode<int>* temp = node->left ? node->left : node->right;
                if (!temp) { temp = node; node = nullptr; }
                else *node = *temp;
                delete temp;
            } else {
                AVLNode<int>* temp = minValueNode(node->right);
                node->key = temp->key;
                node->right = deleteNode(node->right, temp->key);
            }
        }
        if (!node) return node;
        node->height = 1 + std::max(getHeight(node->left), getHeight(node->right));
        int balance = getBalance(node);

        // Left Left
        if (balance > 1 && getBalance(node->left) >= 0)
            return rightRotate(node);
        // Left Right
        if (balance > 1 && getBalance(node->left) < 0) {
            node->left = leftRotate(node->left);
            return rightRotate(node);
        }
        // Right Right
        if (balance < -1 && getBalance(node->right) <= 0)
            return leftRotate(node);
        // Right Left
        if (balance < -1 && getBalance(node->right) > 0) {
            node->right = rightRotate(node->right);
            return leftRotate(node);
        }
        return node;
    }

public:
    void insert(int key) { root = insert(root, key); }
    void remove(int key) { root = deleteNode(root, key); }
    // Destructor omitted for brevity
};

int main() {
    const int N = 14302;
    std::vector<int> keys(N);
    std::iota(keys.begin(), keys.end(), 0);
    std::shuffle(keys.begin(), keys.end(), std::mt19937(42)); // Fixed seed

    // Benchmark Red-Black Tree (std::map)
    {
        std::map<int, int> rbTree;
        auto start = std::chrono::high_resolution_clock::now();
        for (int i : keys) rbTree[i] = i; // Insert
        for (int i : keys) rbTree.erase(i); // Delete
        auto end = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double, std::milli> rbTime = end - start;
        std::cout << "Red-Black Tree (std::map): " << rbTime.count() << " ms\n";
    }

    // Benchmark AVL Tree
    {
        AVLOneInsertDelete avlTree;
        auto start = std::chrono::high_resolution_clock::now();
        for (int i : keys) avlTree.insert(i);
        for (int i : keys) avlTree.remove(i);
        auto end = std::chrono::high_resolution_clock::now();
        std::chrono::duration<double, std::milli> avlTime = end - start;
        std::cout << "AVL Tree: " << avlTime.count() << " ms\n";
    }
}
