            # Process or store the URL immediately
            print "Found: $attr->{href}\n";
            # Or write to a filehandle to avoid storing all in memory
        }
    }, 'tag, attr'],
);

# Open a large file
open my $fh, '<', 'large_dump.html' or die "Cannot open: $!";
$parser->parse_file($fh);
$parser->eof();
```

