    next unless $event->[0] eq 'start' && $event->[1] eq 'a';
    my %attrs = @{$event}[2]; # Attributes are in the 3rd element onward
    if (exists $attrs{'href'}) {
        print $attrs{'href'}, "\n"; # Or store in DB, etc.
    }
}
```

