### ✅ C++ Implementation (`simdjson`)

```cpp
#include <simdjson.h>
#include <iostream>
#include <chrono>

using namespace simdjson;

// Minimal error handling for benchmark clarity
void parse_json(std::string_view json_buffer) {
    ondemand::parser parser;
    auto doc = parser.iterate(json_buffer);

    // Extract a deeply nested value to simulate real work
    auto gdp = doc["properties"]["data"]["metrics"]["value"].get_double();
}

int main() {
    // Load JSON into memory
    std::string json_buffer = load_file("large_json.json"); // 1MB file

    simdjson::default_on_demand::allocator allocator;
    ondemand::parser parser;

    int iterations = 1000;
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < iterations; ++i) {
        try {
            auto doc = parser.iterate(json_buffer);
            double gdp = doc["properties"]["data"]["metrics"]["value"].get_double();
            // Prevent compiler optimization
            asm volatile("" : : "r"(gdp) : "memory");
        } catch (simdjson::error &e) {
            std::cerr << e.what() << std::endl;
            return 1;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();
    std::cout << "C++ (simdjson): " << duration / iterations << " µs per parse" << std::endl;
    return 0;
}
