		err := json.Unmarshal(data, &result)
		if err != nil {
			log.Fatal(err)
		}
	}

	elapsed := time.Since(start)

	// Prevent compiler from optimizing away the loop
	if result == nil {
		log.Fatal("panic")
	}

	elapsedPer := elapsed / time.Duration(iterations)
	log.Printf("Go (encoding/json) - Avg per parse: %v", elapsedPer)
