    std::chrono::duration<double, std::milli> elapsed = end - start;

    std::cout << "C++ (simdjson): " << elapsed.count() << " ms for " << iterations << " iterations\n";
    std::cout << "Avg per parse: " << elapsed.count() / iterations << " ms\n";

