use warnings;

# Better regex: case-insensitive, handles both quotes and no quotes
my @links;
while ($html_content =~ /<a\b[^>]*href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>/gi) {
