### Option 2: Streaming Parser (Recommended for Large Files)

**Do NOT load the entire file into memory.** Process it chunk-by-streaming:

```perl
use strict;
use warnings;
use HTML::TreeBuilder::XPath;  # or HTML::PullParser

sub extract_links_from_file {
    my ($filename) = @_;

    my $parser = HTML::TreeBuilder->new;
    $parser->IGNORE_TAGS({ script => 1, style => 1 });

    # Stream the file (does NOT load entire file into memory at once)
    open my $fh, '<', $filename or die "Can't open $filename: $!";

    while (my $chunk = <$fh>) {
        $parser->parse($chunk);
    }
    $parser->eof;

    my @links;
    for my $link ($parser->look_down(_tag => 'a', href => qr/.*/)) {
        push @links, $link->attr('href');
    }

    $parser->delete;
    return @links;
}

# Usage
my @links = extract_links_from_file('large_dump.html');
```

### Option 3: HTML::PullParser (Most Memory Efficient)

```perl
use strict;
use warnings;
use HTML::PullParser;
use IO::File;

sub extract_links_streaming {
    my ($filename) = @_;

    my $fh = IO::File->new($filename, 'r') or die "Can't open: $!";
    my $parser = HTML::PullParser->new($fh);

    my @links;
    while (my $event = $parser->get_token) {
        next unless $event->is_start_tag('a');
        if (my $href = $event->get_attr('href')) {
            push @links, $href;
        }
    }

    return @links;
}
```

### Option 4: Regex with Slurp in Chunks (If You Insist on Regex)

```perl
use strict;
use warnings;

sub extract_links_regex_chunked {
    my ($filename) = @_;

    open my $fh, '<', $filename or die "Can't open: $!";
    my @links;

    # Read in large chunks to balance memory and regex boundary issues
    my $buffer = '';
    my $chunk_size = 2**20; # 1MB chunks

    while (read($fh, my $chunk, $chunk_size)) {
        $buffer .= $chunk;

        # Process complete HTML tags only
        while ($buffer =~ /<a\b[^>]*href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>/gi) {
            push @links, defined($1) ? $1 : defined($2) ? $2 : $3;
        }

        # Keep partial tag at the end for next chunk
        if ($buffer =~ /<a\b[^>]*$/) {
            $buffer = $&;
        } else {
            $buffer = '';
        }
    }

    # Process any remaining buffer
    while ($buffer =~ /<a\b[^>]*href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))[^>]*>/gi) {
        push @links, defined($1) ? $1 : defined($2) ? $2 : $3;
    }

    return @links;
}
```

