### Benchmarking JIT Overhead Yourself

Here’s a simple way to measure it accurately:

```csharp
using System;
using System.Diagnostics;
using System.Runtime.CompilerServices;

class Program
{
    // Moderately complex method
    static int ComplexMethod(int n)
    {
        int sum = 0;
        for (int i = 0; i < n; i++)
        {
            if (i % 2 == 0) sum += i;
            else sum -= i;
        }
        return sum;
    }

    static void Main()
    {
        // Warm up runtime
        GC.Collect(GC.MaxGeneration, GCCollectionMode.Forced);
        Thread.Sleep(100);

        // Measure cold call
        var sw = Stopwatch.StartNew();
        ComplexMethod(1000);
        sw.Stop();
        Console.WriteLine($"Cold call: {sw.ElapsedTicks} ticks ({sw.Elapsed.TotalMicroseconds:F2} µs)");

        // Measure warm call (average of 1000 calls)
        sw.Restart();
        for (int i = 0; i < 1000; i++)
        {
            ComplexMethod(1000);
        }
        sw.Stop();
        Console.WriteLine($"Warm call (avg): {sw.ElapsedTicks / 1000.0} ticks ({(sw.Elapsed.TotalMicroseconds / 1000):F2} µs)");
    }
}
```

