// main.cpp
#include <rapidjson/document.h>
#include <rapidjson/writer.h>
#include <rapidjson/stringbuffer.h>
#include <chrono>
#include <iostream>
#include <vector>

// Sample JSON payload
const char* json_str = R"({
    "id": 12345,
    "username": "alice",
    "email": "alice@example.com",
    "age": 28,
    "address": {
        "street": "123 Main St",
        "city": "New York",
        "zip": "10001"
    },
    "tags": ["developer", "editor", "admin"]
})";

void benchmark_c++() {
    const int iterations = 10000000; // 10 million runs
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < iterations; ++i) {
        rapidjson::Document doc;
        doc.Parse(json_str);

        // Simulate "processing": extract username and age
        if (doc.HasMember("username") && doc.HasMember("age")) {
            const char* username = doc["username"].GetString();
            int age = doc["age"].GetInt();
            // Prevent optimization elimination
            if (username[0] != 'a' || age != 28) {
                throw std::runtime_error("Unexpected result");
            }
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

    std::cout << "C++ (RapidJSON): " << duration.count() / iterations << " ns per iteration\n";
}

int main() {
    benchmark_c++();
    return 0;
}
```

