// ============================================
// Dual-Pivot QuickSort (Yaroslavskiy's variant, simplified)
// ============================================
void dual_pivot_quicksort(std::vector<int>& arr, int left, int right) {
    if (left >= right) return;

    // Use medians of small samples for pivot selection if range is large
    if (right - left > 50) {
        // Simple pivot selection: three elements
        int mid1 = left + (right - left) / 4;
        int mid2 = left + (right - left) / 2;
        int mid3 = right - (right - left) / 4;

        // Sort these three
        if (arr[mid1] > arr[mid2]) std::swap(arr[mid1], arr[mid2]);
        if (arr[mid2] > arr[mid3]) std::swap(arr[mid2], arr[mid3]);
        if (arr[mid1] > arr[mid2]) std::swap(arr[mid1], arr[mid2]);

        // Use arr[mid1] and arr[mid2] as pi and pj
        int pi = arr[mid1];
        int pj = arr[mid2];

        // Swap pivots into place
        std::swap(arr[left], arr[mid1]);   // pi at left
        std::swap(arr[right], arr[mid2]);  // pj at right

        int lt = left + 1;
        int gt = right - 1;
        int k = left + 1;

        while (k <= gt) {
            if (arr[k] < pi) {
                std::swap(arr[k], arr[lt]);
                lt++;
                k++;
            } else if (arr[k] >= pj) {
                std::swap(arr[k], arr[gt]);
                gt--;
                // k not incremented; newly swapped element unprocessed
            } else {
                k++;
            }
        }

        // Place pivots
        lt--; gt++;
        std::swap(arr[left], arr[lt]);
        std::swap(arr[right], arr[gt]);

        // Recurse
        dual_pivot_quicksort(arr, left, lt - 1);
        dual_pivot_quicksort(arr, lt + 1, gt - 1);
        dual_pivot_quicksort(arr, gt + 1, right);
    } else {
        // Small arrays: fall back to insertion sort for efficiency
        for (int i = left + 1; i <= right; i++) {
            int key = arr[i];
            int j = i - 1;
            while (j >= left && arr[j] > key) {
                arr[j + 1] = arr[j];
                j--;
            }
            arr[j + 1] = key;
        }
    }
}

void sort_dual_pivot_quick(std::vector<int>& arr) {
    dual_pivot_quicksort(arr, 0, arr.size() - 1);
