// ============================================
// Timsort Implementation (simplified, faithful to CPython/Java logic)
// ============================================
const int MIN_MERGE = 32;

inline int get_run_length(const std::vector<int>& arr, int start, int n, bool ascending) {
    int i = start + 1;
    if (ascending) {
        while (i < n && arr[i] >= arr[i - 1]) i++;
    } else {
        while (i < n && arr[i] < arr[i - 1]) i++;
    }
    return i - start;
}

void reverse_range(std::vector<int>& arr, int lo, int hi) {
    while (lo < hi) {
        std::swap(arr[lo], arr[hi]);
        lo++; hi--;
    }
}

int count_run_and_make_ascending(std::vector<int>& arr, int start, int n) {
    int run_len = 0;
    if (start == n - 1) return 1;

    // Check if ascending or descending
    if (arr[start + 1] >= arr[start]) {
        // Ascending run
        run_len = get_run_length(arr, start, n, true);
        if (run_len < MIN_MERGE) {
            // Binary insertion sort for short run
            run_len = std::min(run_len, n - start);
            for (int i = start + 1; i < start + run_len; i++) {
                int key = arr[i];
                int lo = start, hi = i - 1;
                while (lo <= hi) {
                    int mid = lo + (hi - lo) / 2;
                    if (arr[mid] <= key) lo = mid + 1;
                    else hi = mid - 1;
                }
                std::rotate(arr.begin() + lo, arr.begin() + i, arr.begin() + i + 1);
            }
        }
    } else {
        // Descending run: reverse to make ascending
        run_len = get_run_length(arr, start, n, false);
        reverse_range(arr, start, start + run_len - 1);
        if (run_len >= MIN_MERGE) {
            return run_len;
        }
        // Binary insertion sort for remaining
        int end = std::min(start + run_len, n);
        for (int i = start + 1; i < end; i++) {
            int key = arr[i];
            int lo = start, hi = i - 1;
            while (lo <= hi) {
                int mid = lo + (hi - lo) / 2;
                if (arr[mid] <= key) lo = mid + 1;
                else hi = mid - 1;
            }
            std::rotate(arr.begin() + lo, arr.begin() + i, arr.begin() + i + 1);
        }
    }
    return run_len;
}

// Merge two runs: arr[start..mid) and arr[mid..end)
void merge(std::vector<int>& arr, std::vector<int>& buf, int start, int mid, int end) {
    int n1 = mid - start;
    int n2 = end - mid;

    // Copy to buffer
    memcpy(buf.data(), arr.data() + start, sizeof(int) * (n1 + n2));

    int i = 0, j = n1, k = start;
    while (i < n1 && j < n1 + n2) {
        if (buf[i] <= buf[j]) {
            arr[k++] = buf[i++];
        } else {
            arr[k++] = buf[j++];
        }
    }
    while (i < n1) arr[k++] = buf[i++];
    while (j < n1 + n2) arr[k++] = buf[j++];
}

void sort_timsort(std::vector<int>& arr) {
    int n = arr.size();
    if (n <= 1) return;

    std::vector<int> buf(n);
    std::vector<std::pair<int, int>> stack; // (run_start, run_length)

    int min_run = n;
    while (min_run >= MIN_MERGE) min_run >>= 1;

    int current = 0;
    while (current < n) {
        int run_len = count_run_and_make_ascending(arr, current, n);
        if (run_len < min_run) {
            int force = std::min(min_run, n - current);
            // Binary insertion sort for 'force' elements
            for (int i = current + 1; i < current + force; i++) {
                int key = arr[i];
                int lo = current, hi = i - 1;
                while (lo <= hi) {
                    int mid = lo + (hi - lo) / 2;
                    if (arr[mid] <= key) lo = mid + 1;
                    else hi = mid - 1;
                }
                std::rotate(arr.begin() + lo, arr.begin() + i, arr.begin() + i + 1);
            }
            run_len = std::min(run_len, force);
        }

        stack.push_back({current, run_len});
        current += run_len;

        // Merge if necessary: maintain that no two adjacent runs satisfy
        // stack[-2].length + stack[-1].length > stack[-3].length + ...
        while (stack.size() >= 2) {
            auto& a = stack[stack.size() - 2];
            auto& b = stack[stack.size() - 1];
            if (a.second + b.second < (stack.size() >= 3 ? stack[stack.size() - 3].second : 0)) {
                if (a.second < b.second) {
                    merge(arr, buf, a.first, a.first + a.second, a.first + a.second + b.second);
                    b.first = a.first;
                    b.first += 0; // already at a.first
                    b.second += a.second;
                    stack.pop_back();
                } else {
                    merge(arr, buf, a.first, a.first + a.second, a.first + a.second + b.second);
                    a.second += b.second;
                    stack.pop_back();
                }
            } else if (a.second < b.second) {
                merge(arr, buf, a.first, a.first + a.second, a.first + a.second + b.second);
                b.first = a.first;
                b.second += a.second;
                stack.pop_back();
            } else {
                break;
            }
        }
    }

    // Final merges until one run remains
    while (stack.size() > 1) {
        auto& a = stack[stack.size() - 2];
        auto& b = stack[stack.size() - 1];
        merge(arr, buf, a.first, a.first + a.second, a.first + a.second + b.second);
        a.second += b.second;
        stack.pop_back();
    }
}

