using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

class Benchmark
{
    static void Main()
L{
        const int N = 10_000_000;

        // Generate test data: every 3rd number is "kept"
        var source = new int[N];
        for (int i = 0; i < N; i++)
        {
            source[i] = i;
        }

        int warmupCount = 3;
        int iterationCount = 10;

        // --- Warmup ---
        for (int w = 0; w < warmupCount; w++)
        {
            var _1 = source.Where(x => x % 3 == 0).ToList();
            var _2 = FilterWithFor(source);
        }

