        var linqTimes = new List<double>();
        for (int i = 0; i < iterationCount; i++)
        {
            var sw = Stopwatch.StartNew();
            var resultLinq = source.Where(x => x % 3 == 0).ToList();
            sw.Stop();
            linqTimes.Add(sw.Elapsed.TotalMilliseconds);
        }

        // --- Measure traditional for loop ---
        var forTimes = new List<double>();
        for (int i = 0; i < iterationCount; i++)
        {
            var sw = Stopwatch.StartNew();
            var resultFor = FilterWithFor(source);
            sw.Stop();
            forTimes.Add(sw.Elapsed.TotalMilliseconds);
        }

        // --- Results ---
        double avgLinq = linqTimes.Average();
        double avgFor = forTimes.Average();

        Console.WriteLine($"Source size: {N:N0} elements");
        Console.WriteLine($"{new string('-', 50)}");
        Console.WriteLine($"LINQ .Where().ToList(): avg {avgLinq:F2} ms  (min: {linqTimes.Min():F2} ms, max: {linqTimes.Max():F2} ms)");
        Console.WriteLine($"Traditional for loop:   avg {avgFor:F2} ms  (min: {forTimes.Min():F2} ms, max: {forTimes.Max():F2} ms)");
        Console.WriteLine($"{new string('-', 50)}");
        Console.WriteLine($"Speedup: {(avgLinq / avgFor):F2}x faster with for loop");

        // Verify correctness
        Console.WriteLine($"\nResult counts match: {source.Count(x => x % 3 == 0) == resultFor.Count}");
    }

    static List<int> FilterWithFor(IEnumerable<int> source)
    {
        List<int> result = new List<int>();
        foreach (int value in source)
        {
            if (value % 3 == 0)
            {
                result.Add(value);
            }
        }
        return result;
    }
}
