#include <chrono>
#include <vector>
#include <cstdlib>
#include <ctime>

// Assume you have AVLTree and RBTree implementations
// Use std::map for RB (libstdc++ uses RB)
#include <map>

void benchmark_rb() {
    std::map<int, int> rbTree;
    std::vector<int> ops(14302);
    for (int& op : ops) op = rand();

    auto start = std::chrono::high_resolution_clock::now();
    for (int val : ops) {
        if (rand() % 2 == 0) rbTree.insert({val, val});
        else {
            auto it = rbTree.find(val);
            if (it != rbTree.end()) rbTree.erase(it);
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "RB: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";
}

void benchmark_avl() {
    AVLTree<int, int> avlTree; // Your custom AVL
    std::vector<int> ops(14302);
    for (int& op : ops) op = rand();

    auto start = std::chrono::high_resolution_clock::now();
    for (int val : ops) {
        if (rand() % 2 == 0) avlTree.insert(val, val);
        else {
            if (avlTree.find(val)) avlTree.erase(val);
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    std::cout << "AVL: " << std::chrono::duration_cast<std::chrono::microseconds>(end - start).count() << " us\n";
