    }
    return low;
}

static int galloping_right(uint32_t arr[], int low, int high, uint32_t key) {
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] <= key)
            low = mid + 1;
        else
            high = mid;
    }
    return low;
}

// Merge two runs: [lo, mid) and [mid, hi)
static void merge(uint32_t arr[], int lo, int mid, int hi, uint32_t *temp) {
    int n1 = mid - lo;
    int n2 = hi - mid;

    if (n1 <= 0 || n2 <= 0) return;

    // If first element of right run is <= last of left, no merge needed
    if (arr[mid - 1] <= arr[mid]) return;

    // Use temp buffer
    memcpy(temp + lo, arr + lo, (hi - lo) * sizeof(uint32_t));

    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (temp[i] <= temp[j]) {
            arr[k++] = temp[i++];
        } else {
            arr[k++] = temp[j++];
        }
