// Insertion sort for small runs
static void insertion_sort(uint32_t arr[], int lo, int hi) {
    for (int i = lo + 1; i < hi; i++) {
        uint32_t key = arr[i];
        int j = i - 1;
        while (j >= lo && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

// Timsort
void timsort(uint32_t arr[], int n) {
    uint32_t *temp = malloc(n * sizeof(uint32_t));
    if (!temp) { return; }

    int min_run = MIN_RUN;

    // Sort individual runs
    for (int start = 0; start < n; start += min_run) {
        int end = start + min_run;
        if (end > n) end = n;
        insertion_sort(arr, start, end);
    }

    // Merge runs
    for (int size = min_run; size < n; size *= 2) {
        for (int left = 0; left < n; left += 2 * size) {
            int mid = left + size;
            int right = left + 2 * size;
            if (mid >= n) break;
            if (right > n) right = n;
            merge(arr, left, mid, right, temp);
        }
    }

    free(temp);
}

