            "vector", initial_size, NUM_INSERTIONS, make_small);
        benchmark_insertions<std::list<SmallElement>, SmallElement>(
            "list",   initial_size, NUM_INSERTIONS, make_small);
    }

    std::cout << "\n=== Large Element (128 bytes) ===\n";
    std::cout << std::setw(12) << "Container"
