    return scalar @links;
}

# Method 2: Improved regex
sub improved_regex {
    my @links = $html =~ /<a\b[^>]*\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|(\S+))[^>]*>/gi;
    my @hrefs;
    while (@links) {
        my $h = shift(@links) // shift(@links) // shift(@links);
        push @hrefs, $h if defined $h;
    }
    return scalar @hrefs;
}

# Method 3: HTML::LinkExtor (streaming single pass)
sub parser_method {
    require HTML::LinkExtor;
    my $count = 0;
    HTML::LinkExtor->new(sub {
        $count++ if $_[0] eq 'a' && exists $_[1]{href};
    })->parse($html);
    return $count;
}

cmpthese(-5, {
    original  => \&original_regex,
