### Code (C++: nlohmann/json)
```cpp
#include <nlohmann/json.hpp>
#include <chrono>
#include <vector>
#include <iostream>

struct User {
    int id;
    std::string name;
    std::string city;
    double score_sum;
};

std::vector<User> parse_with_nlohmann(const std::string& json_str) {
    auto j = nlohmann::json::parse(json_str);
    std::vector<User> users;
    users.reserve(j["users"].size());

    for (auto& u : j["users"]) {
        User usr;
        usr.id = u["id"].get<int>();
        usr.name = u["name"].get<std::string>();
        usr.city = u["address"]["city"].get<std::string>();
        usr.score_sum = 0.0;
        for (auto& s : u["scores"]) {
            usr.score_sum += s.get<double>();
        }
        users.push_back(std::move(usr));
    }
    return users;
}
```

### Code (C++: Custom Zero-Allocation Parser)
```cpp
// Custom flat-buffer JSON parser (rapidjson-inspired, no heap allocs during parse)
#include <cstring>
#include <vector>

struct User {
    int id;
    const char* name;      // non-owning pointer into buffer
    int name_len;
    const char* city;
    int city_len;
    double score_sum;
};

// Simplified: Assumes well-formed JSON matching schema
std::vector<User> custom_parse(const char* json, size_t len) {
    std::vector<User> users;
    users.reserve(10000);

    const char* ptr = json;
    // Skip to first '{' then "users": [...]
    while (*ptr != '[') ptr++;
    ptr++; // skip '['

    while (*ptr == ' ') ptr++;
    if (*ptr == ']') break;

    while (*ptr) {
        // Parse user object
        const char* obj_start = ptr;
        if (*ptr != '{') { ptr++; continue; }
        ptr++;

        // Parse id
        while (*ptr != 'i' || *(ptr+1) != 'd') ptr++;
        ptr += 4; // skip "id":
        while (*ptr != ':') ptr++; ptr++;
        while (*ptr == ' ') ptr++;
        int id = 0;
        while (isdigit(*ptr)) { id = id * 10 + (*ptr - '0'); ptr++; }

        // Parse name
        while (*ptr != 'n' || *(ptr+1) != 'a') ptr++;
        ptr += 5; // skip "name":
        while (*ptr != ':') ptr++; ptr++;
        while (*ptr == ' ' || *ptr == '\n') ptr++;
        char quote = *ptr++; // skip opening '"'
        const char* name_start = ptr;
        while (*ptr != '"') {
            if (*ptr == '\\') ptr++; // skip escape
            ptr++;
        }
        ptr++; // skip closing '"'
        char name_buf[256];
        int name_len_copy = ptr - name_start;
        memcpy(name_buf, name_start, name_len_copy);
        name_buf[name_len_copy] = '\0';

        // Parse city (simplified: assume path is "address":{"city":...)
        while (*ptr != 'c' || *(ptr+1) != 'i') ptr++;
        ptr += 5; // skip "city":
        while (*ptr != ':') ptr++; ptr++;
        while (*ptr == ' ' || *ptr == '\n') ptr++;
        ptr++; // skip '"'
        const char* city_start = ptr;
        while (*ptr != '"') ptr++;
        ptr++;
        char city_buf[256];
        int city_len_copy = ptr - city_start;
        memcpy(city_buf, city_start, city_len_copy);
        city_buf[city_len_copy] = '\0';

        // Parse scores array
        double score_sum = 0.0;
        while (*ptr != 's' || *(ptr+1) != 'c') ptr++;
        ptr += 7; // skip "scores":
        while (*ptr != ':') ptr++; ptr++;
        while (*ptr == ' ' || *ptr == '\n') ptr++;
        if (*ptr == '[') ptr++;
        while (*ptr != ']') {
            while (*ptr == ' ' || *ptr == ',') ptr++;
            double score = 0.0;
            bool decimal = false;
            int divisor = 1;
            while (isdigit(*ptr) || *ptr == '.') {
                if (*ptr == '.') { decimal = true; }
                else {
                    if (decimal) { divisor *= 10; }
                    score = score * 10 + (*ptr - '0');
                }
                ptr++;
            }
            score_sum += score / divisor;
        }
        ptr++; // skip ']'

        users.push_back({id, name_buf, name_len_copy, city_buf, city_len_copy, score_sum});

        // Advance past object
        while (*ptr != '}') ptr++;
        ptr++; // skip '}'
        while (*ptr == ' ' || *ptr == ',') ptr++;
        if (*ptr == ']') break;
    }
    return users;
}
```

