    std::chrono::duration<double, std::milli> elapsed = end - start;

    std::cout << "C++ (RapidJSON): " << Iterations << " iterations in " 
              << elapsed.count() << " ms\n";
    std::cout << "C++ (RapidJSON): Avg " 
              << (elapsed.count() / Iterations) << " ms per parse\n";

