### 3. C++ Implementation

We compare two approaches:
1. **`nlohmann/json`**: The行业标准 (industry standard) for ease of use. It is highly optimized but still allocates nodes.
2. **`simdjson`**: A state-of-the-art parser that uses SIMD instructions to parse JSON at near memory-bandwidth limits. It is non-validating in some modes and uses arena allocation.

#### `main.cpp`
```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <chrono>
#include <vector>

#include <nlohmann/json.hpp>
#include <simdjson.h>

const int ITERATIONS = 100000;

void benchmark_nlohmann(const std::string& json_str) {
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < ITERATIONS; ++i) {
        // nlohmann/json is copy-on-write and uses small object optimization
        nlohmann::json j = nlohmann::json::parse(json_str);
        // Do something minimal to prevent compiler optimization
        volatile auto id = j["id"].get<int>();
        volatile auto name = j["name"].get<std::string>();
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> duration = end - start;
    std::cout << "nlohmann/json: " << duration.count() << " ms (" 
              << (duration.count() * 1000.0 / ITERATIONS) << " µs/op)\n";
}

void benchmark_simdjson(const std::string& json_str) {
    simdjson::dom::parser parser;
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < ITERATIONS; ++i) {
        // simdjson is very fast but requires careful error handling in production
        simdjson::dom::element doc = parser.parse(json_str);
        volatile auto id = doc["id"];
        volatile auto name = doc["name"].get_string();
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double, std::milli> duration = end - start;
    std::cout << "simdjson: " << duration.count() << " ms (" 
              << (duration.count() * 1000.0 / ITERATIONS) << " µs/op)\n";
}

int main() {
    std::ifstream file("test.json");
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return 1;
    }

    std::stringstream buffer;
    buffer << file.rdbuf();
    std::string json_str = buffer.str();
    file.close();

    std::cout << "--- C++ Benchmarks ---" << std::endl;

    benchmark_nlohmann(json_str);
    benchmark_simdjson(json_str);

    return 0;
}
