## 🔹 C++ Implementation: `simdjson`

### File: `cpp_json_benchmark.cpp`
```cpp
#include <iostream>
#include <chrono>
#include <vector>
#include <memory>
#include "simdjson.h"

// Include simdjson header (you must link against simdjson library)
// GitHub: https://github.com/simdjson/simdjson

int main() {
    // Read the JSON file once
    std::ifstream file("large.json");
    if (!file.is_open()) {
        std::cerr << "Failed to open file\n";
        return 1;
    }
    std::string buffer((std::istreambuf_iterator<char>(file)),
                        std::istreambuf_iterator<char>());
    file.close();

    const auto json = simdjson::minify(buffer); // Return a parsed JSON object
    if (json.error()) {
        std::cerr << "Parse error: " << json.error() << "\n";
        return 1;
    }

    // Benchmark: Parse the raw buffer 1,000,000 times
    const int iterations = 1'000'000;
    auto start = std::chrono::high_resolution_clock::now();

    simdjson::ondemand::parser simd_parser;
    for (int i = 0; i < iterations; ++i) {
        auto doc = simd_parser.iterate(buffer);
        // Access a field to prevent compiler from optimizing away the parse
        auto root = doc.get_root();
        auto key = root["key"];
        (void)key; // Suppress unused variable warning
    }

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<double> elapsed = end - start;

    std::cout << "C++ (simdjson): " << iterations << " parses in "
              << elapsed.count() << " seconds\n";
    std::cout << "Throughput: " << (iterations / elapsed.count()) << " parses/sec\n";
    return 0;
}
```

