    auto start = std::chrono::high_resolution_clock::now();

    {
        Container c;
        // Pre-fill with some data
        for (int i = 0; i < num_elements; ++i) {
            c.push_back(value + i);
        }

        // Perform insertions at random middle positions
        std::mt19937 rng(42);
        std::uniform_int_distribution<int> pos_dist(0, num_elements);

for (int i = 0; i < num_insertions; ++i) {
    auto it = std::next(c.begin(), pos_dist(rng));
    c.insert(it, value + num_elements + i);
    ++num_elements; // track growing size
    pos_dist = std::uniform_int_distribution<int>(0, num_elements);
    }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    std::cout << Container_name<Container>()
              << ": " << num_insertions << " inserts into ~" 
              << (num_elements - num_insertions) << " elems = " 
              << duration << " ms\n";
}

template<typename Container> std::string Container_name() = delete;
template<> std::string Container_name<std::vector<int>>() { return "std::vector<int>"; }
template<> std::string Container_name<std::list<int>>() { return "std::list<int>"; }

