	"encoding/json"
	"fmt"
)

type Record struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
}

func parseStdLib(data []string) []Record {
	results := make([]Record, 0, len(data))
	var r Record
	for _, jsonStr := range data {
		err := json.Unmarshal([]byte(jsonStr), &r)
		if err != nil {
			// Error handling omitted for benchmark purity
			continue
		}
		results = append(results, r)
	}
	return results
}
```

#### Option B: `jsoniter` (High-Performance Go Library)
*`jsoniter` is the Go community’s answer to fast JSON. It uses runtime code generation.*

```go
