var jsoniter = jsoniter.ConfigCompatibleWithStandardLibrary

func parseJsoniter(data []string) []Record {
	results := make([]Record, 0, len(data))
	var r Record
	for _, jsonStr := range data {
		err := jsoniter.Unmarshal([]byte(jsonStr), &r)
		if err != nil {
			continue
		}
		results = append(results, r)
	}
	return results
