    for (size_t i = 0; i < num_insertions; ++i) {
        size_t pos = dis(gen);
        // Insert at random position in the middle/anywhere
        v.insert(v.begin() + pos, 42);
    }
    auto end = high_resolution_clock::now();
    return duration_cast<microseconds>(end - start).count();
}

// Function to benchmark std::list
double benchmark_list(size_t initial_size, size_t num_insertions) {
    std::list<int> l(initial_size, 0);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, l.size() - 1);

    auto start = high_resolution_clock::now();
    for (size_t i = 0; i < num_insertions; ++i) {
        size_t pos = dis(gen);
        // Advance iterator to position
        auto it = std::next(l.begin(), pos);
        l.insert(it, 42);
    }
    auto end = high_resolution_clock::now();
    return duration_cast<microseconds>(end - start).count();
}

void run_benchmarks() {
    size_t insertions = 10'000;
    std::cout << "Performing " << insertions << " random mid-point insertions.\n";
    std::cout << std::left << std::setw(15) << "Initial Size (N)" 
              << std::setw(20) << "Vector (µs)" 
              << std::setw(20) << "List (µs)" 
              << std::setw(15) << "Speedup (V/L)" << "\n";
    std::cout << std::string(70, '-') << "\n";

    std::vector<size_t> sizes = {1'000, 10'000, 100'000, 1'000'000};

    for (size_t n : sizes) {
        double vec_time = benchmark_vector(n, insertions);
        double list_time = benchmark_list(n, insertions);
        double ratio = list_time / vec_time;

        std::cout << std::left << std::setw(15) << n 
                  << std::setw(20) << std::fixed << std::setprecision(2) << vec_time 
                  << std::setw(20) << list_time 
                  << std::setw(15) << ratio << "x" << "\n";
    }
}

int main() {
    run_benchmarks();
    return 0;
}
```

