#include <cstdio>
#include <chrono>
#include "simdjson.h"

// Load entire file into memory
char* load_file(const char* filename, size_t* length) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Could not open file\n");
        exit(1);
    }
    fseek(file, 0, SEEK_END);
    *length = ftell(file);
    fseek(file, 0, SEEK_SET);
    char* buffer = (char*)malloc(*length);
    fread(buffer, 1, *length, file);
    fclose(file);
    return buffer;
}

int main() {
    const char* filename = "large.json";
    size_t length = 0;
    char* input = load_file(filename, &length);

    simdjson::dom::parser parser;

    // Warm-up phase
    simdjson::dom::element doc;
    for (int i = 0; i < 100; i++) {
        parser.parse(input, length).get(doc);
    }

    // Benchmark phase
    auto start = std::chrono::high_resolution_clock::now();
    int iterations = 10000;
    for (int i = 0; i < iterations; i++) {
        parser.parse(input, length).get(doc);
    }
    auto end = std::chrono::high_resolution_clock::now();

    std::chrono::duration<double, std::micro> diff = end - start;
    double avg_time_ns = diff.count() / iterations;

    printf("C++ (simdjson): %f nanoseconds per parse\n", avg_time_ns);

    free(input);
    return 0;
}
```

