struct AVLNode {
    int key;
    AVLNode *left = nullptr;
    AVLNode *right = nullptr;
    int height = 1;

    static int heightOf(AVLNode* n) { return n ? n->height : 0; }

    static int getBalance(AVLNode* n) {
        return n ? heightOf(n->left) - heightOf(n->right) : 0;
    }

    static AVLNode* rightRotate(AVLNode* y) {
        AVLNode* x = y->left;
        AVLNode* T2 = x->right;
        x->right = y;
        y->left = T2;
        y->height = 1 + std::max(heightOf(y->left), heightOf(y->right));
        x->height = 1 + std::max(heightOf(x->left), heightOf(x->right));
        return x;
