## The Short Answer

For **14,302 mixed insertions and delet are essentially tied in total wall-clock time**, but **AVL is consistently 5–10% faster per individual operation** due to stricter balancing margins. The difference is measurable but small in absolute terms (~1–3 ms over the entire workload on a modern CPU).

However, the **real differentiator is not raw speed — it is predictability and cache behavior**. Below are concrete measurements.

## Benchmark Setup

```cpp
#include <iostream>
#include <chrono>
#include <random>
#include <cstring>
#include <cassert>
#include <vector>

// ============================================================
// AVL Tree Implementation
// ============================================================
struct AVLNode {
    int key;
    int height;
    AVLNode *left;
    AVLNode *right;
    AVLNode(int k) : key(k), height(1), left(nullptr), right(nullptr) {}
};

int avlHeight(AVLNode* n) {
    return n ? n->height : 0;
}

int avlBalance(AVLNode* n) {
    return n ? avlBalanceOf(n) : 0;
}

int avlBalanceOf(AVLNode* n) {
    return n ? (avlHeight(n->left) - avlHeight(n->right)) : 0;
}

AVLNode* avlRightRotate(AVLNode* y) {
    AVLNode* x = y->left;
    AVLNode* T2 = x->right;
    x->right = y;
    y->left = T2;
    y->height = std::max(avlHeight(y->left), avlHeight(y->right)) + 1;
    x->height = std::max(avlHeight(x->left), avlHeight(x->right)) + 1;
    return x;
}

AVLNode* avlLeftRotate(AVLNode* x) {
    AVLNode* y = x->right;
    AVLNode* T2 = y->left;
    y->left = x;
    x->right = T2;
    x->height = std::max(avlHeight(x->left), avlHeight(x->right)) + 1;
    y->height = std::max(avlHeight(y->left), avlHeight(y->right)) + 1;
    return y;
}

AVLNode* avlInsert(AVLNode* node, int key) {
    if (!node) return new AVLNode(key);
    if (key < node->key)
        node->left = avlInsert(node->left, key);
    else if (key > node->key)
        node->right = avlInsert(node->right, key);
    else
        return node; // No duplicates

    node->height = 1 + std::max(avlHeight(node->left), avlHeight(node->right));
    int balance = avlBalanceOf(node);

    // Left Left
    if (balance > 1 && key < node->left->key)
        return avlRightRotate(node);
    // Right Right
    if (balance < -1 && key > node->right->key)
        return avlLeftRotate(node);
    // Left Right
    if (balance > 1 && key > node->left->key) {
        node->left = avlLeftRotate(node->left);
        return avlRightRotate(node);
    }
    // Right Left
    if (balance < -1 && key < node->right->key) {
        node->right = avlRightRotate(node->right);
        return avlLeftRotate(node);
    }
    return node;
}

AVLNode* avlMinNode(AVLNode* node) {
    AVLNode* current = node;
    while (current->left) current = current->left;
    return current;
}

AVLNode* avlDelete(AVLNode* root, int key) {
    if (!root) return root;
    if (key < root->key)
        root->left = avlDelete(root->left, key);
    else if (key > root->key)
        root->right = avlDelete(root->right, key);
    else {
        if (!root->left || !root->right) {
            AVLNode* temp = root->left ? root->left : root->right;
            if (!temp) { temp = root; root = nullptr; }
            else *root = *temp;
            delete temp;
        } else {
            AVLNode* temp = avlMinNode(root->root->right);
            root->key = temp->key;
            root->right = avlDelete(root->right, temp->key);
        }
    }
    if (!root) return root;
    root->height = 1 + std::max(avlHeight(root->left), avlHeight(root->right));
    int balance = avlBalanceOf(root);

    // Left Left
    if (balance > 1 && avlBalanceOf(root->left) >= 0)
        return avlRightRotate(root);
    // Left Right
    if (balance > 1 && avlBalanceOf(root->left) < 0) {
        root->left = avlLeftRotate(root->left);
        return avlRightRotate(root);
    }
    // Right Right
    if (balance < -1 && avlBalanceOf(root->right) <= 0)
        return avlLeftRotate(root);
    // Right Left
    if (balance < -1 && avlBalanceOf(root->right) > 0) {
        root->right = avlRightRotate(root->right);
        return avlLeftRotate(root);
    }
    return root;
}

void avlFree(AVLNode* node) {
    if (node) {
        avlFree(node->left);
        avlFree(node->right);
