    return h && h->color;
}

RBNode* rbLeftRotate(RBNode* h) {
    RBNode* x = h->right;
    h->right = x->left;
    x->left = h;
    x->color = h->color;
    h->color = true;
    return x;
}

RBNode* rbRightRotate(RBNode* h) {
    RBNode* x = h->left;
    h->left = x->right;
    x->right = h;
    x->color = h->color;
    h->color = true;
    return x;
}

void rbFlipColors(RBNode* h) {
    h->color = !h->color;
    h->left->color = !h->left->color;
    h->right->color = !h->right->color;
}

RBNode* rbInsert(RBNode* h, int key) {
    if (!h) return new RBNode(key);
    if (key < h->key)
        h->left = rbInsert(h->left, key);
    else if (key > h->key)
        h->right = rbInsert(h->right, key);
    else
        return h;

    // Fix-up right-leaning red links
    if (isRed(h->right) && !isRed(h->left))
        h = rbLeftRotate(h);
    if (isRed(h->left) && isRed(h->left->left))
        h = rbRightRotate(h);
    if (isRed(h->left) && isRed(h->right))
        rbFlipColors(h);
    return h;
}

RBNode* rbMoveRedLeft(RBNode* h) {
    rbFlipColors(h);
    if (isRed(h->right->left)) {
        h->right = rbRightRotate(h->left);
        h = rbLeftRotate(h);
        rbFlipColors(h);
    }
    return h;
}

RBNode* rbMoveRedRight(RBNode* h) {
    rbFlipColors(h);
    if (isRed(h->left->left)) {
        h = rbRightRotate(h);
        rbFlipColors(h);
    }
    return h;
}

RBNode* rmDeleteMin(RBNode* h) {
    if (!h->left) { delete h; return nullptr; }
    if (!isRed(h->left) && !isRed(h->left->left))
        h = rbMoveRedLeft(h);
    h->left = rmDeleteMin(h->left);
    return rbBalance(h);
}

RBNode* rbBalance(RBNode* h) {
    if (isRed(h->right) && !isRed(h->left))
        h = rbLeftRotate(h);
    if (isRed(h->left) && isRed(h->left->left))
        h = rbRightRotate(h);
    if (isRed(h->left) && isRed(h->right))
        rbFlipColors(h);
    h->size = (h->left ? h->left->size : 0) + (h->right ? h->right->size : 0) + 1;
    return h;
}

RBNode* rbDelete(RBNode* h, int key) {
    if (key < h->key) {
        if (!isRed(h->left) && !isRed(h->left->left))
            h = rbMoveRedLeft(h);
        h->left = rbDelete(h->left, key);
    } else {
        if (isRed(h->left))
            h = rbRightRotate(h);
        if (key == h->key && !h->right) {
            delete h;
            return nullptr;
        }
        if (!isRed(h->right) && !isRed(h->right->left))
            h = rbMoveRedRight(h);
        if (key == h->key) {
            RBNode* min = h->right;
            while (min->left) min = min->left;
            h->key = min->key;
            h->right = rmDeleteMin(h->right);
        } else
            h->right = rbDelete(h->right, key);
    }
    return rbBalance(h);
}

void rbFree(RBNode* node) {
    if (node) {
        rbFree(node->left);
        rbFree(node->right);
        delete node;
    }
}

