@Measurement(iterations = 10, time = 1)
@Fork(3)
public class SortBenchmark {

    private static final int SIZE = 14_302;
    private int[] primitiveRandom;
    private Integer[] objectRandom;

    @Setup
    public void setup() {
        Random rng = new Random(42);
        primitiveRandom = new int[SIZE];
        objectRandom = new Integer[SIZE];
