        int[] copy = primitiveRandom.clone();
        Arrays.sort(copy); // JDK uses Dual-Pivot Quicksort for int[]
    }

    // Timsort on objects
    @Benchmark
    public void sortObjectTimsort() {
        Integer[] copy = objectRandom.clone();
        Arrays.sort(copy); // JDK uses Timsort for Integer[]
    }

    // Dual-Pivot Quicksort on objects (manual)
    @Benchmark
    public void sortObjectDualPivot() {
        Integer[] copy = objectRandom.clone();
        // Use a custom dual-pivot quicksort implementation for Integer[]
        customDualPivotQuickSort(copy, 0, copy.length - 1);
    }

    // Your custom dual-pivot quicksort here
    private void customDualPivotQuickSort(Integer[] a, int lo, int hi) {
        if (lo >= hi) return;
        // ... your implementation ...
    }

    public static void main(String[] args) throws Exception {
        org.openjdk.jmh.Main.main(args); // Should not be run directly; use jmh runner
    }
